window.NIGHTS=window.NIGHTS||{cases:{}};
window.NIGHTS.cases[8]={"nr":8,"id":"case08","title":"Daheim ist daheim","subtitle":"","level":"Kriminelle Ebene","from":209,"to":232,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":209,"layer":null,"blocks":3},{"id":"bescheidene-anfaenge","kind":"place","title":"BESCHEIDENE ANFÄNGE","page":210,"layer":null,"blocks":6},{"id":"aufstieg-auf-der-immobilienleiter","kind":"place","title":"AUFSTIEG AUF DER IMMOBILIENLEITER","page":210,"layer":null,"blocks":12},{"id":"wildknock-die-naechste-mahlzeit","kind":"place","title":"WILDKNOCK, DIE NÄCHSTE MAHLZEIT","page":211,"layer":null,"blocks":29},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":214,"layer":null,"blocks":7},{"id":"verlassene-hauptstrasse","kind":"place","title":"VERLASSENE HAUPTSTRASSE","page":214,"layer":"schicht-0-aufhaenger","blocks":20},{"id":"schicht-1-die-strassen-von-wildknock","kind":"layer","title":"SCHICHT 1: DIE STRASSEN VON WILDKNOCK","page":216,"layer":null,"blocks":2},{"id":"kanzlei-clarke","kind":"place","title":"KANZLEI CLARKE","page":216,"layer":"schicht-1-die-strassen-von-wildknock","blocks":21},{"id":"kirche-des-heiligen-geistes","kind":"place","title":"KIRCHE DES HEILIGEN GEISTES","page":217,"layer":"schicht-1-die-strassen-von-wildknock","blocks":12},{"id":"chicken-egg-food-truck","kind":"place","title":"CHICKEN & EGG FOOD TRUCK","page":218,"layer":"schicht-1-die-strassen-von-wildknock","blocks":8},{"id":"schicht-2","kind":"layer","title":"SCHICHT 2","page":220,"layer":null,"blocks":15},{"id":"grey-alley","kind":"place","title":"GREY ALLEY","page":221,"layer":"schicht-2","blocks":15},{"id":"zuhause-der-navarros","kind":"place","title":"ZUHAUSE DER NAVARROS","page":222,"layer":"schicht-2","blocks":26},{"id":"rice-immobilien","kind":"place","title":"RICE IMMOBILIEN","page":224,"layer":"schicht-2","blocks":24},{"id":"schicht-3","kind":"layer","title":"SCHICHT 3","page":227,"layer":null,"blocks":2},{"id":"die-grabhoehle","kind":"place","title":"DIE GRABHÖHLE","page":227,"layer":"schicht-3","blocks":37},{"id":"fritzberg","kind":"place","title":"FRITZBERG","page":230,"layer":"schicht-3","blocks":11},{"id":"schicht-4-das-herz-des-boesen","kind":"layer","title":"SCHICHT 4: DAS HERZ DES BÖSEN","page":231,"layer":null,"blocks":1},{"id":"evas-elternhaus","kind":"place","title":"EVAS ELTERNHAUS","page":231,"layer":"schicht-4-das-herz-des-boesen","blocks":24}],"pages":{"209":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN BLUTIGER FALL UM ZERRÜTTETE FAMILIENVERHÄLTNISSE</b>","sz":20.0,"box":[87.6,776.1,507.7,796.1],"p":209,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"210":{"tab":"","blocks":[{"t":"p","x":"„Menschen wie Sie hatten nie wirklich Hunger. Vielleicht hatten Sie es mal schwer. Vielleicht mussten Sie ein oder zwei Mahlzeiten auslassen. Aber waren Sie jemals so hungrig, dass ein einziges, alles beherrschendes Gefühl die Vernunft ertränkt, ein endloses Magenknurren, das Sie anfleht, die Leere zu füllen? So sehr schmachte ich danach, dass dieser Deal zustande kommt. Ich will es so sehr, dass ich es schmecken kann, und ich kann für nichts garantieren, wenn ich ihn nicht bekomme. Also seien Sie ein Schatz und unterschreiben Sie die Papiere. Ich verspreche Ihnen, morgen Abend werden Sie sich nicht einmal daran erinnern, jemals in diesem elenden Loch gelebt zu haben ...“","sz":13.0,"box":[53.9,60.1,286.2,319.6],"p":210,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Daheim ist daheim</i> ist ein klassischer Monster-Fall, der Horrorelemente mit der Thematik des Turbokapitalismus verbindet. Als das Team in einem heruntergekommenen Viertel eintrifft, führen Ermittlungen über ein halbseidenes Immobiliengeschäft und die mythische Jagd nach dem Monster, das durch die Straßen streift, zu ein und derselben Frau. Sobald die Schurkin aufgetaucht ist, erweist sie sich als eine Bedrohung, die dem Schlimmsten, was das Team je gesehen hat, ebenbürtig ist, und die Ermittlungen kehren sich um: Das Team wird zur Beute und muss herausfinden, wie es das Monster überwinden kann, bevor es zu seiner Mahlzeit wird. Zu allem Überfluss setzen die Überlebensinstinkte die Logik außer Kraft und treiben möglicherweise dazu an, unaussprechliche Taten zu begehen.","sz":9.5,"box":[53.9,330.1,285.2,514.6],"p":210,"i":1,"sec":"titel-und-pitch"},{"t":"h","x":"BESCHEIDENE ANFÄNGE","sz":16.0,"box":[53.9,566.6,211.4,582.6],"p":210,"i":2,"skip":true,"sec":"bescheidene-anfaenge"},{"t":"p","x":"<b>Eva Rice</b> (Wendigo) wuchs in einer zerrütteten Familie auf. Ihre alkoholkranken Eltern, die oft arbeitslos und in endlose häusliche Streitigkeiten verwickelt waren, waren nicht in der Lage, sich um ihre Tochter oder ihr Haus, ein kleines Anwesen im Stadtteil <b>Fritzberg</b>, zu kümmern. Dementsprechend war Evas Kindheit von Hunger, Vernachlässigung und Gewalt geprägt. Zur Strafe sperrten ihre Eltern sie häufig in den Keller des Hauses, wo sie stundenlang saß, frierend und hungrig.","sz":9.5,"box":[53.9,586.6,285.5,696.1],"p":210,"i":3,"sec":"bescheidene-anfaenge"},{"t":"p","x":"Eines Tages, kurz vor Evas achtzehntem Geburtstag, sperrten ihre Eltern sie für mehrere Tage ein. Im Alko-","sz":9.5,"box":[53.9,704.7,283.3,726.7],"p":210,"i":4,"sec":"bescheidene-anfaenge"},{"t":"p","x":"holrausch hatten sie sie einfach vergessen. Eingesperrt und verzweifelt überschritt Evas Frustration über die eigene Ohnmacht eine neue Schwelle. Jahre der Armut, des Leids und der Entbehrungen verdichteten sich zu einem alles verzehrenden schwarzen Loch in ihrem Herzen. Sie erwachte, und als ihre Eltern die Tür öffneten, stürzte sich der Wendigo auf sie, verschlang sie und ließ nichts als Knochen übrig. Eva vergrub die sterblichen Überreste im überwucherten Hinterhof.","sz":9.5,"box":[309.0,59.9,540.0,169.4],"p":210,"i":5,"sec":"bescheidene-anfaenge"},{"t":"p","x":"An diesem Tag schwor Eva, fortan all ihre Bedürfnisse zu befriedigen und sich in der Macht des Wendigos zu sonnen. Obwohl sie fast immer hungrig war – ihr Mythos ist die Verkörperung des alles verschlingenden Konsums – stellte sie sicher, dass sie immer die Kraft hatte, diesen Hunger zu stillen.","sz":9.5,"box":[309.0,178.1,538.6,250.1],"p":210,"i":6,"sec":"bescheidene-anfaenge"},{"t":"p","x":"Als die Macht des Wendigos in ihr wuchs, wurde Eva fast unbesiegbar, aber für ihre Unsicherheit war „fast“ nicht genug. In dem Bestreben, auch über ihre Sterblichkeit Macht zu haben, erfuhr sie durch ihren Mythos, dass man sie nur töten könnte, wenn man <b>ihr Herz mit einem silbernen Messer in kleine Stücke schnitt</b>. Deshalb schnitt sie sich selbst das Herz heraus und versteckte es im ehemaligen Haus ihrer Eltern.","sz":9.5,"box":[309.0,258.8,541.0,355.8],"p":210,"i":7,"sec":"bescheidene-anfaenge"},{"t":"h","x":"AUFSTIEG AUF DER IMMOBILIENLEITER","sz":16.0,"box":[309.0,371.4,439.6,404.4],"p":210,"i":8,"skip":true,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"Eva, die herzlos und ehrgeizig, aber im Grunde nur ein wilder Teenager war, übernahm Gelegenheitsjobs und bildete sich weiter. Sie bestanden die Abendschule und begann, in den Arbeitervierteln als Immobilienmaklerin zu arbeiten. Unter ihrem neuen, kultivierten Äußeren lauerten nach wie vor wilde Triebe, und sie verschlang jeden, der sich ihr in den Weg stellte.","sz":9.5,"box":[309.0,408.4,537.6,492.9],"p":210,"i":9,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"Innerhalb weniger Jahre erklomm sie die Erfolgsleiter auf dem Immobilienmarkt der Stadt. Durch eine Reihe scheinbar glücklicher Zufälle beim Kauf und Verkauf von Immobilien florierte das Geschäft, und sie konnte ihre eigene Agentur eröffnen: <b>Rice Immobilien</b>. Ihre Agentur entwickelte sich zu einem der am schnellsten wachsenden Immobilienbüros der Stadt und machte Eva zu einer der reichsten und am meisten bewunderten Unternehmerinnen der Elite des Finanzdistrikts.","sz":9.5,"box":[309.0,501.5,537.2,611.0],"p":210,"i":10,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"<b>Das Geheimnis des Erfolges von Rice Immobilien ist der Wendigo</b>. Evas legendärer Hunger, der sie dazu treibt, sich von den Schwachen zu ernähren, wodurch sie in heruntergekommenen Stadtvierteln zur Immobilienmagnatin wurde, lässt das Unternehmen florieren. Ihre Strategie beruht auf roher Gewalt und Rücksichtslosigkeit:","sz":9.5,"box":[309.0,619.8,540.9,704.2],"p":210,"i":11,"sec":"aufstieg-auf-der-immobilienleiter"}],"size":[595.276,841.89]},"211":{"tab":"","blocks":[{"t":"p","x":"• Sie designiert eine verschlafene Gegend von geringem Wert als ihre nächste Futterstelle.","sz":9.5,"box":[53.9,59.9,276.6,81.9],"p":211,"i":0,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"• Sie sucht die Umgebung als Wendigo heim, stillt ihren Hunger und schickt so die Anwohner:innen auf die Suche nach einem sicheren Zuhause.","sz":9.5,"box":[53.9,90.6,286.1,125.1],"p":211,"i":1,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"• Dank des Nebels glauben die Schläfer:innen, dass es sich bei den verschwundenen Anwohner:innen um Aussteiger:innen handelt.","sz":9.5,"box":[53.9,133.8,281.6,168.3],"p":211,"i":2,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"• Der Wert der Immobilien in der Umgebung sinkt. Rice Immobilien greift zu, kauft preisgünstige Immobilien und vernachlässigt sie, damit die Preise weiter sinken.","sz":9.5,"box":[53.9,176.9,273.6,223.9],"p":211,"i":3,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"• Der Wert der Immobilien in der Umgebung sinkt weiter. Rice Immobilien kauft alle verbleibenden Grundstücke auf.","sz":9.5,"box":[53.9,232.6,267.0,267.1],"p":211,"i":4,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"• Eva verkauft die Grundstücke an ein Sanierungsunternehmen und verspricht, es werde nach der Sanierung ein Vermögen wert sein. In Wahrheit ist das Viertel so heruntergekommen und unbeliebt, dass eine Sanierung finanziell nicht machbar ist. Das Sanierungsunternehmen verschiebt es auf unbestimmte Zeit, das Viertel erholt sich nie wieder.","sz":9.5,"box":[53.9,275.8,284.6,360.3],"p":211,"i":5,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"• Eva wendet sich ihrem nächsten Ziel zu.","sz":9.5,"box":[53.9,368.9,231.8,378.4],"p":211,"i":6,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"p","x":"Das erste Stadtviertel, das diesen Prozess durchlief, war Evas Heimatbezirk Fritzberg. Nachdem sich Rice Immobilien dort zurückgezogen hatte, wurde den Käufer:innen klar, dass sie den ehrgeizigen Sanierungsplan nicht finanzieren konnten, und die Häuser blieben leer. Bis heute sieht Alt-Fritzberg wie eine Geisterstadt aus, in der Gras zwischen leeren Anwesen und verlassenen Baustellen wuchert.","sz":9.5,"box":[53.9,384.3,286.5,481.3],"p":211,"i":7,"sec":"aufstieg-auf-der-immobilienleiter"},{"t":"h","x":"WILDKNOCK, DIE NÄCHSTE MAHLZEIT","sz":16.0,"box":[53.9,497.0,214.1,530.0],"p":211,"i":8,"skip":true,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Rice hat als nächstes Jagdgebiet das Arbeiterviertel <b>Wildknock</b> auserkoren – ein kolonialer Name, der sich von dem indigenen Wynoynock ableitet. Wie überall sucht Eva zuerst die Straßen heim, als Unternehmerin als auch als Wendigo. Sie bringt ihre Opfer zum Verzehr in die <u>Grabhöhle</u> unter dem <b>Feenring-Spielplatz</b> in Wildknock. Um die Beweise im wahrsten Sinne des Wortes zu begraben, baut Rice Immobilien ein Einkaufszentrum über der Höhle.","sz":9.5,"box":[53.9,533.9,285.3,643.4],"p":211,"i":9,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"<b>Wildknock befindet sich in rasantem Verfall.</b> Langjährige Bewohner:innen ziehen in Scharen weg. Der Geist des Wendigo zerfrisst das soziale Gefüge und vernebelt den Bewohner:innen den Verstand mit einem übernatürlichen Hunger, so wie Eva physisch ihre Leiber frisst. Geräumte oder spärlich besiedelte Bauwerke verfallen.","sz":9.5,"box":[53.9,652.2,277.3,736.5],"p":211,"i":10,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"h","x":"EIN DUNKLER PAKT – UND VERRAT!","sz":14.0,"box":[320.3,61.0,484.8,75.0],"p":211,"i":11,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Wenn du die Kampagne spielst, haben Eva Rice und Vince Beaumont einen dunklen Pakt geschlossen, der Teil von Beaumonts Wettrüsten gegen den König in Karmesin ist.","sz":9.0,"box":[320.3,87.5,529.0,132.5],"p":211,"i":12,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Eva hat es auf Wohnviertel entlang der Grenzen zu Albion abgesehen. Sobald sie sie ausgesaugt hat und verlassen und heruntergekommen zurücklässt, übernehmen der Nebel und Albion die Kontrolle und verwandeln sie in ein mittelalterliches Wunderland. Davon profitieren beide Seiten: Eva muss nicht mehr hinter sich aufräumen, während Beaumont seine Enklave auf den Leichen vergangener Viertel errichtet.","sz":9.0,"box":[320.3,141.2,527.6,234.2],"p":211,"i":13,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Natürlich planen beide, sich gegeneinander zu wenden. Eva setzt auf Albion als üppigen Wald, in dem sie sich frei bewegen und nähren kann und in dem sie die mysteriösen Männer in Grau nicht fürchten muss. Je größer, desto köstlicher wäre es, Albion schließlich zu verzehren. Andererseits mästet Beaumont Eva für die Schlachtbank: Als geschmähte Kreatur, die unsägliches Unrecht begangen hat, ist sie die perfekte Kandidatin für das Questentier (s. S. 177). Beaumont setzt darauf, dass eine Held:in sie erschlagen wird. Er hofft auf die Freisetzung immenser magischer Energie, die er für seinen Krieg nutzen kann. Deshalb schickt er das Team auf die Suche nach der Lösung der Mordfälle in Wildknock.","sz":9.0,"box":[320.3,242.8,529.3,407.8],"p":211,"i":14,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Einige aufmerksame Bürger:innen Wildknocks haben Evas Angriff auf ihre Gemeinde bemerkt und versucht, sie zu entlarven:","sz":9.5,"box":[309.0,440.5,538.1,475.0],"p":211,"i":15,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"• Die erste war <b>Jackie Clarke (Schläferin) [ERMOR- DET]</b> – eine örtliche Anwältin <u>(Kanzlei Clarke),</u> die an einer einstweiligen Verfügung arbeitete, um die Übernahme des Viertels durch Rice Immobilien zu verhindern. Der Wendigo hat sie entführt, in die Grabhöhle gebracht und verzehrt.","sz":9.5,"box":[309.0,486.5,538.0,558.5],"p":211,"i":16,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"• Die zweite war <b>Mia Gupta (Annapurna, Hindu- Gottheit – Göttin des Essens und der Ernährung) [GEFANGEN]</b> – Köchin im <u>Chicken &amp; Egg Food Truck,</u> die Zeugin eines von Evas Morden war und entdeckt wurde. Sie versuchte, Nachbar:innen und Kund:innen von dem Monster zu erzählen, aber am nächsten Abend fing Eva sie in der <u>Grey Alley</u> ab. Eva entdeckte, dass Gupta ihre legendären Kräfte einsetzen kann, um den Hunger des Wendigo vorübergehend zu stillen, und so hält sie sie in der <u>Grabhöhle</u> am Leben, bis sie weiß, was sie mit ihr machen soll.","sz":9.5,"box":[309.0,567.2,540.8,701.7],"p":211,"i":17,"sec":"wildknock-die-naechste-mahlzeit"}],"size":[595.276,841.89]},"212":{"tab":"","blocks":[{"t":"p","x":"• Der dritte war <b>Privatdetektiv Luis Navarro (Gwelab’hot, amerikanischer Medizingeist) [ERMOR- DET]</b> – ein pensionierter Polizist, der im Auftrag Jackie Clarkes gegen Rice Immobilien ermittelte und Träume über den umherstreifenden Wendigo hatte. Er beschattete Mia Gupta, nachdem er hörte, dass sie am Einkaufszentrum etwas Schreckliches gesehen haben wollte, und kam rechtzeitig in der <u>Grey Alley</u> an, um gegen den Wendigo zu kämpfen, wenn auch erfolglos. Mit Hilfe seiner Kräfte gelang es Navarro, einen Blick auf Evas größtes Geheimnis zu werfen, nämlich, dass ihr Herz fehlt und wo es sein könnte, bevor er mutig und töricht in ihr Versteck eindrang, um Mia zu retten. <b>Sein Geist spukt in Wildknock.</b>","sz":9.5,"box":[53.9,114.9,285.2,287.0],"p":212,"i":0,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"• Jetzt ist nur noch <b>Pfarrerin Keisha Williams (Ala, Igbo-Gottheit der Moral, Gesellschaft und der Seelen der Toten)</b> übrig – die Pfarrerin der örtlichen Kirche des Heiligen Geistes, die sich um die","sz":9.5,"box":[53.9,295.6,279.5,342.6],"p":212,"i":1,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Gemeinde sorgt. Dank ihrer Verbindungen und erwachenden Mythos-Kräfte ist ihr klar, dass etwas das lokale soziale Gefüge attackiert.","sz":9.5,"box":[317.5,112.4,540.5,146.9],"p":212,"i":2,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Um den Fall zu lösen, muss das Team herausfinden, was Wildknock auffrisst, Eva und den Immobilienplan entlarven und einen Weg finden, sie zu besiegen, wozu es den Aufbewahrungsort ihres Herzens finden muss.","sz":9.5,"box":[309.0,152.7,538.9,199.7],"p":212,"i":3,"sec":"wildknock-die-naechste-mahlzeit"}],"size":[595.276,841.89]},"213":{"tab":"","blocks":[{"t":"h","x":"DIE WENDIGO- PSYCHOSE","sz":23.0,"box":[53.9,63.4,189.4,114.4],"p":213,"i":0,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Eva Rices Macht geht weit über die Verwandlung in ein Monster hinaus: Sie kann andere in Monster verwandeln, indem sie deren Moral mit so schmerzhaften Hunger erschüttert, dass es sie um den Verstand bringt. Je mehr Eva ein Viertel kontrolliert, desto mehr erfüllt ihr Einfluss es und führt zu der <b>Wendigo-Psychose</b>.","sz":13.0,"box":[53.9,122.3,285.7,251.5],"p":213,"i":1,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"<b>Zu Beginn des Falles ist die Wendigo-Psychose in Wildknock nur schwach ausgeprägt</b> und wirkt sich nur auf die aus, die bereits ihrem Überlebensinstinkt erlegen sind (s. S. Thorn Sørensen und die Plünderer in der verlassenen Hauptstraße). Die meisten Menschen reagieren auf das allgegenwärtige Gefühl des Mangels, indem sie sich mit Lebensmitteln eindecken, sich „verbarrikadieren“ oder, wenn sie klug sind, abwandern, weil sie spüren, dass das Viertelverloren ist.","sz":9.5,"box":[53.9,262.0,285.5,371.4],"p":213,"i":2,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"<b>Mit jeder Schicht wird der Effekt mächtiger</b>. Am ersten Schauplatz einer neuen Schicht erhalten alle SC und begleitende NSC den Zustand Hungrig mit einer Stufe, die der Schicht entspricht (<t>hungrig 1</t>, <t>ausgehungert 2</t>, <t>am Verhungern 3</t>, <t>vom Hunger verzehrt 4</t>). Die Bezeichnung dieses Zustands kannst du so ändern, dass sie einen beliebigen Überlebensinstinkt widerspiegelt, z. B. das Bedürfnis nach Wärme, einem Dach über dem Kopf, Wasser, Migration, Fortpflanzung, Herdenschutz usw. Optional kannst du bildlichere Formen des Hungers nutzen, wie z. B. den emotionalen Hunger nach Aufmerksamkeit oder den geistigen nach Unterhaltung (Fernsehen, Filme, Bücher).","sz":9.5,"box":[53.9,380.0,284.0,552.0],"p":213,"i":3,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Wenn du einem SC zum ersten Mal diesen Zustand gibst, frage die Spieler:in:","sz":9.5,"box":[53.9,560.7,267.6,582.7],"p":213,"i":4,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"sh","x":"<b>? WAS IST DAS STÄRKSTE INSTINKTIVE BEDÜRFNIS DEINES CHARAKTERS?</b>","sz":10.0,"box":[54.3,596.3,273.6,618.3],"p":213,"i":5,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Eva Rice und ihre Schergen können die Wendigo-Psychose direkt durch <t>Hunger</t>-Zustände zufügen. Unabhängig davon, ob es sich um einen Umgebungs- oder direkten Effekt handelt, können SC ihm mit Stärken begegnen, die Widerstand gegen psychische Effekte bieten. Wenn sie es als Mythos-Effekt identifizieren, sind auch magische Verteidigungen anwendbar.","sz":9.5,"box":[53.9,623.9,279.9,708.4],"p":213,"i":6,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Der Zustand Wendigo-Psychose zwingt Charaktere, ihren Hunger zu stillen. Er behindert jede Handlung, die nicht direkt auf die Befriedigung der Bedürfnisse abzielt. Wenn der Zustand Wendigo-Psychose be-","sz":9.5,"box":[53.9,717.0,275.2,764.0],"p":213,"i":7,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"friedigt wird, ruht er für den Rest der Szene, wird aber nicht entfernt. Zu Beginn der nächsten Szene nimmt er die Wirkung wieder auf. Nur wer der Psychose widersteht oder sie magisch entfernt, kann seine Selbstbeherrschung wiedererlangen (vermutlich durch <b>Das Blatt wenden</b> oder Ausgeben von Momentum aus anderen Quellen). Eine andere Möglichkeit wäre, einen Monat (<b>Drehpause</b>) fernab von Wildknock und Eva zu verbringen, um sich von der Psychose zu erholen.","sz":9.5,"box":[309.0,59.9,541.5,169.4],"p":213,"i":8,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"sh","x":"<b>BEDROHUNGEN MIT DER WENDIGO-PSYCHOSE</b>","sz":10.0,"box":[309.4,183.0,444.8,205.0],"p":213,"i":9,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"NSC, die von der Wendigo-Psychose betroffen sind, haben zwei zusätzliche Spektren. Erstens können sie für eine Szene, genau wie SC, ihren <i>Hunger temporär stillen</i>, z. B. durch Einkauf von Nahrung. Dieses Spektrum wird am Ende der Szene zurückgesetzt, wenn der Hunger wiederkommt. Zweitens können die SC den Geist der Opfer magisch verändern, beeinflussen oder vor der Psychose abschirmen und dann versuchen, <i>Psychose umkehren</i> auf den Höchstwert zu bringen. Dazu sind legendäre Fähigkeiten nötig, solange sie sich in Wildknock oder in der Nähe Evas befinden. Weltliche psychologische Ratschläge helfen nur, wenn sich das Opfer außerhalb von Evas Einflussbereich befindet.","sz":9.5,"box":[309.0,210.6,540.8,382.6],"p":213,"i":10,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"h","x":"DER ANGST-FAKTOR","sz":15.0,"box":[320.3,415.7,448.7,430.7],"p":213,"i":11,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Du kannst dem Fall ein Horrorelement hinzufügen, indem du seltsame Vorkommnisse schilderst, bei denen die Wendigo-Psychose in den Alltag eindringt.","sz":9.0,"box":[320.3,436.3,529.2,469.3],"p":213,"i":12,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Der unablässige Hunger scheint den SC unter die Haut zu gehen und ihre Wahrnehmung zu stören. Sie haben das Gefühl, als jage man sie, als tauche hinter jeder Straßenlaterne ein monströser Schatten auf – eine namenlose Bestie, gekrönt von einem prächtigen Geweih. Ein eisiger Wind oder Schneegestöber wehen heran und verwandeln eine Gasse in eine verschneite Waldlichtung, die von knorrigen Bäumen umgeben ist, nur um im nächsten Moment wieder zur Normalität zurückzukehren (eine Anspielung auf die Verbindung des Wendigos zu strengen Wintern).","sz":9.0,"box":[320.3,477.9,529.1,606.9],"p":213,"i":13,"sec":"wildknock-die-naechste-mahlzeit"},{"t":"p","x":"Wenn Eva und die von der Wendigo-Psychose Betroffenen angreifen, mach es bluttriefend, um den kannibalischen Eifer widerzuspiegeln (wenn deine Gruppe das verträgt). Beschreibe mit Stufe-6-Zustandwerten, wie sie Opfern Gliedmaßen abreißen und sie verschlingen.","sz":9.0,"box":[320.3,615.6,518.7,684.6],"p":213,"i":14,"sec":"wildknock-die-naechste-mahlzeit"}],"size":[595.276,841.89]},"214":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 0:","sz":14.0,"box":[53.9,61.9,122.3,75.9],"p":214,"i":0,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23.0,"box":[53.9,84.2,170.2,107.2],"p":214,"i":1,"skip":true},{"t":"p","x":"Folgendermaßen kannst du das Team in den Fall einbeziehen:","sz":9.5,"box":[53.9,115.7,278.0,137.7],"p":214,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Eine Queste des Königs</b>: Wenn du die Kampagne spielst, kann <b>Vince Beaumont</b> (König Artus) dem Team die Queste geben, dem „Nachbarkönigreich“ Wildknock zu helfen, indem es die heimtückische Übeltäter:in aufspürt, die dessen Straßen heimsucht, und vor Gericht bringt. So hofft er, die Prophezeiung des Questentiers zu erfüllen. Umgekehrt können SCs, die Albion beobachten, feststellen, dass es sich ausbreitet und in benachbarte Stadtblöcke und -bezirke eindringt. Dieser schleichende Effekt hat nun den Rand Wildknocks erreicht und verharrt dort, als warte er auf etwas. In jedem Fall sind der <u>Chicken &amp; Egg Food Truck</u> oder die <u>Kirche des Heiligen Geistes</u> gute Anlaufstellen, um sich umzuhören.","sz":9.5,"box":[53.9,146.3,285.3,318.3],"p":214,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Ein Plädoyer für die Gemeinde</b>: <b>Pfarrerin Williams</b> kann sich an das Team wenden und es anheuern, um herauszufinden, was ihre Gemeinde bedroht. Sie wird die SC einladen, die Dinge in der <u>Kirche des Heiligen Geistes</u> zu besprechen.","sz":9.5,"box":[53.9,327.0,285.5,386.5],"p":214,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Sich abzeichnendes Muster:</b> Teammitglieder, die in Kontakt mit Beamt:innen, führenden Persönlichkeiten der Gemeinde oder Immobilienmakler:innen stehen, erhalten vielleicht einen Hinweis auf ein Immobilienprojekt in der Stadt. <b>Rice Immobilien</b> scheint sich in Mittelklasse-Viertel einzukaufen und dann alles fiktiv (oder auch nicht) aufzufressen und wieder auszuspucken. In den Vierteln, die aktuell betroffen sind, scheint die Gemeinschaft auseinanderzufallen, da viele Bewohner:innen ausziehen. Während dies direkt zu <u>Rice Immobilien</u> in Schicht 2 führen könnte, schlägt der Kontakt des Teams vor, dass sie ihre Ermittlungen bei <u>Kanzlei Clarke</u> beginnen, die sich juristisch gegen die Übernahme stellt.","sz":9.5,"box":[53.9,395.2,282.7,567.2],"p":214,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Ein Vermisstenfall</b>: Eine Person aus der Subkultur der Risse, die Mia Gupta nahe steht, könnte nach ihr suchen. Das könnte ein Riss-Kollege sein, mit dem sie früher im Bowl abhing (s. S. <i>Athanor</i>, S. 94), oder eine Nebenfigur der Serie. Mia arbeitet als Köchin im <u>Chicken &amp; Egg Food Truck</u> in Wildknock. Die Kontaktperson hat seit einer Woche nichts von ihr gehört und macht sich Sorgen. Da sie Gefahr wittern, möchte sie, dass das Team nach Wildknock fährt, um nach ihr zu sehen oder sie dorthin begleitet.","sz":9.5,"box":[53.9,575.8,285.9,697.8],"p":214,"i":6,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"Was immer der Grund für die Ankunft der SC in Wildknock sein mag und wohin sie gehen, sie landen auf der <u>verlassenen Hauptstraße.</u>","sz":9.5,"box":[53.9,703.7,279.5,738.2],"p":214,"i":7,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"VERLASSENE HAUPTSTRASSE","sz":16.0,"box":[334.8,68.9,529.2,84.9],"p":214,"i":8,"skip":true,"sec":"verlassene-hauptstrasse"},{"t":"ro","x":"Trostlosigkeit und leere Straßen begrüßen euch in Wildknock. Das dicht bebaute Viertel mit Mietskasernen und Reihenhäusern scheint verlassen. Man sieht wenige Bewohner:innen die Straßen überqueren und über die Schulter schauen, als suchten sie eilig Schutz. Lose vernagelte Fenster klappern, wenn Wind durch die entkernten Häuser weht. Die Hauptstraße wirkt ausgezehrt, wie leer gefegt. Ein großes Plakat des Maklerbüros RICE IMMOBILIEN verspricht, dass hier ein Neubaugebiet entstehen wird, doch die derzeitige Situation scheint katastrophal. Warum sind alle verschwunden?","sz":9.0,"box":[317.5,87.3,538.9,247.5],"p":214,"i":9,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"Die Ankunft der SC in Wildknock prägt den Schauplatz und die Stimmung für den gesamten Fall: <b>Ein mächtiges Unternehmen, Rice Immobilien, verleibt sich ein heruntergekommenes Viertel ein.</b> Das Team kann mit den Einwohner:innen sprechen und bekommt einen Eindruck davon, was vor sich geht. Während es die Straße erkundet, tauchen die ersten Anzeichen für das Wirken des Wendigo auf.","sz":9.5,"box":[309.0,256.5,541.4,353.5],"p":214,"i":10,"sec":"verlassene-hauptstrasse"},{"t":"card","x":"Anwohner:innen erzählen dem Team vom <b>rapiden Niedergang des Viertels</b> in letzter Zeit: Menschen ziehen weg (manche sagen „verschwinden“), Häuser werden unter Wert verkauft. Niemand weiß, wie es dazu kam, aber es hat eine Flucht aus Wildknock ausgelöst.","sz":null,"k":"yellow","box":[309.3,364.6,541.7,445.8],"p":214,"i":11,"sec":"verlassene-hauptstrasse"},{"t":"card","x":"<b>Einige Menschen scheinen sich mit Lebensmitteln und anderen Vorräten des täglichen Bedarfs einzudecken.</b> Als Grund nennen sie „Vorsorge für den Winter“, unabhängig von der aktuellen Jahreszeit.","sz":null,"k":"yellow","box":[309.3,454.5,541.7,523.9],"p":214,"i":12,"sec":"verlassene-hauptstrasse"},{"t":"card","x":"<b>Eine Anfrage beim Grundbuchamt zeigt, dass Rice Immobilien Wildknock praktisch aufgekauft hat.</b> RI ist dafür bekannt, aggressiv Gebäude zu erwerben und im großen Stil zur Sanierung zu verkaufen. In den letzten Jahren hat RI einen kometenhaften Aufstieg erlebt.","sz":null,"k":"yellow","box":[309.3,532.5,541.7,614.0],"p":214,"i":13,"sec":"verlassene-hauptstrasse"},{"t":"card","x":"<b>Jenseits des Nebels</b> sieht der Ort aus wie ein verschneiter Winterwald, ein Friedhof aus leblosen Baumstämmen. Ein mit einem Geweih gekrönter Schatten huscht aus dem Blickfeld. Das Gefühl der Entbehrung liegt in der Luft und scheint in den Bewohner:innen unbändigen Hunger zu wecken. Es gibt keine Quelle für diese gefährliche Kraft. Der einzige Ort, an dem sie ein wenig nachlässt, ist die <u>Kirche des Heiligen Geistes</u> am Ende der Hauptstraße.","sz":null,"k":"yellow","box":[309.3,622.7,541.7,752.0],"p":214,"i":14,"sec":"verlassene-hauptstrasse"}],"size":[595.276,841.89]},"215":{"tab":"","blocks":[{"t":"sh","x":"<b>PLÜNDERUNGEN</b>","sz":10.0,"box":[54.3,62.8,145.8,72.8],"p":215,"i":0,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"Einige der Einwohner:innen, die eher zu Gier und Horten neigen, haben sich daran gemacht, die mit Brettern verkleideten verlassenen Läden auf der Straße zu plündern. Wenn die SC diese Plünder:innen angreifen, behandle sie als Straßengang (s. S. 286), ein Kollektiv mit einem Größenfaktor von 2 mit den Spektren <i>Psychose umkehren 2</i> und <i>Hunger temporär stillen 2</i>.","sz":9.5,"box":[53.9,78.3,284.0,162.8],"p":215,"i":1,"sec":"verlassene-hauptstrasse"},{"t":"sh","x":"<b>THORN SØRENSENS WÖLFISCHER RÜCK- FALL</b>","sz":10.0,"box":[54.3,176.4,276.4,198.4],"p":215,"i":2,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"Wenn es zu deinen cineastischen Überlegungen passt, kannst du den Fall mit einem Knall eröffnen, indem ein vom Hunger wahnsinniger Riss das Team überfällt, sobald es im Viertel ankommt.","sz":9.5,"box":[53.9,204.0,283.9,251.0],"p":215,"i":3,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"In der verlassen Hauptstraße wohnt <b>Thorn Sørensen</b>, ein Riss Isegrims, des hungrigen anthropomorphen Wolfs aus <i>Reineke Fuchs</i> (oder alternativ der große böse Wolf). Der stämmige, tätowierte Feuerwehrmann mit borstigen Vollbart ist ein anständiger, freundlicher Kerl. Allerdings hat er eine Vergangenheit, die mit seinem wölfischen Appetit zusammenhängt: Von Gier getrieben drang er in ein Hotel ein und fraß sich am Büffet durch, bis er fünfmal so groß war, verscheuchte die Gäste und verprügelte alle Sicherheitsleute, die versuchten, ihn aufzuhalten. Der Agent der Torwächter:innen löste das Problem, indem er ihn einschläferte.","sz":9.5,"box":[53.9,259.7,286.2,406.7],"p":215,"i":4,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"Jetzt hat die Wendigo-Psychose Thorn wieder erweckt und in einen heißhungrigen Menschenfresser verwandelt. Aufgrund seines eigenen Mythos ist er für den Hungereffekt des Wendigos anfällig und ist ihm schneller erlegen als andere. Er ist bereits hungrig ge-","sz":9.5,"box":[53.9,415.3,281.3,474.8],"p":215,"i":5,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"nug, um Menschenfleisch zu fressen. Als das Team bei seiner Adresse, einem schäbigen Mietshaus, ankommt, stürzt er sich aus der Dunkelheit des Flurs auf einen der SC oder gar auf ihr vorbeifahrendes Auto.","sz":9.5,"box":[309.0,59.9,539.4,106.9],"p":215,"i":6,"sec":"verlassene-hauptstrasse"},{"t":"threat","stars":"★★★","name":"ZORNIGER ISEGRIM","spectra":"","items":[],"box":[417.0,153.8,447.6,165.8],"p":215,"i":7,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"Wenn er Isegrim kanalisiert, verwandelt sich Thorn in eine Kreatur, die einem Werwolf ähnelt: Muskeln schwellen zu unmenschlichen Proportionen, ihm wächst ein dichtes, graumeliertes Fell sowie Klauen und Reißzähne, und er wird zu einer riesigen Bestie. Dennoch behält er einen Teil seines Verstandes und des Geschicks. Als Waffe trägt er eine große Feuerwehraxt.","sz":9.0,"box":[317.5,177.0,569.0,246.0],"p":215,"i":8,"sec":"verlassene-hauptstrasse"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 6 / PSYCHOSE UM- KEHREN 4 / HUNGER TEMPORÄR STILLEN 4</b>","sz":12.0,"box":[317.5,256.5,568.9,280.5],"p":215,"i":9,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"• <b>Grausam</b>: Im Nahkampf versucht Isegrim zunächst Angreifer:in zu beißen, seine Klauen in sie zu versenken oder mit der Axt auf sie einzuhacken (<t>zerfleischt 3</t>). • <b>Hackebeil</b>: Wenn Isegrim mit seiner <i>Feuerwehraxt</i> angreift, behindert diese Stärke <b>Sich der Gefahr stellen</b>, wenn Gegner:innen den Schlag blocken oder absorbieren wollen. • <b>Dickes Fell, stumpfe Sinne</b>: Wenn Isegrim einen Zustand der körperlichen Verletzung oder des Unschädlichmachens erleidet, reduziert sich die Stufe um 1.","sz":9.0,"box":[317.5,285.0,564.4,390.0],"p":215,"i":10,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"• Jemanden mit den Klauen aufschlitzen, beißen oder mit der Axt spalten (<t>zerfleischt 3</t>) • Jemanden anspringen, umstoßen und am Boden festhalten (<t>niedergehalten 3</t>) • Ein gebissenes Opfer mit der Wendigo-Psychose (<t>hungrig 1</t>) infizieren, die man für Lykanthropie halten könnte","sz":9.0,"box":[317.5,399.0,564.3,468.0],"p":215,"i":11,"sec":"verlassene-hauptstrasse"},{"t":"p","x":"• Auf allen vieren kauern, die Krallen in den Boden graben und zum Angriff übergehen • Seine Beute anbrüllen, sabbern und nach Blut schnüffeln","sz":9.0,"box":[317.5,477.0,569.7,510.0],"p":215,"i":12,"sec":"verlassene-hauptstrasse"}],"size":[595.276,841.89]},"216":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 1:","sz":14.0,"box":[53.9,61.9,120.8,75.9],"p":216,"i":0,"skip":true,"sec":"schicht-1-die-strassen-von-wildknock"},{"t":"h","x":"DIE STRASSEN VON WILDKNOCK","sz":23.0,"box":[53.9,84.2,235.8,135.2],"p":216,"i":1,"skip":true},{"t":"p","x":"Nachdem das Team Zeuge des rapiden Niedergangs von Wildknock geworden ist, könnte es herausfinden wollen, woher er rührt und wie die Ermittlungen weitergehen können. Je mehr die SC sich mit den Geschichten einzelner Gemeindemitglieder befassen, desto mehr enthüllen sie das eigentliche Grauen hinter dem Zusammenbruch des Bezirks.","sz":13.0,"box":[53.9,143.1,281.5,286.6],"p":216,"i":2,"sec":"schicht-1-die-strassen-von-wildknock"},{"t":"h","x":"KANZLEI CLARKE","sz":16.0,"box":[79.7,305.2,191.2,321.2],"p":216,"i":3,"skip":true,"sec":"kanzlei-clarke"},{"t":"ro","x":"Auf den ersten Blick könnte die Kanzlei Clarke eine weitere Kanzlei in einem Wohnhaus wie jedes andere sein. Die zerbrochene Glastür am Ende des Korridors erzählt aber eine andere Geschichte. Inmitten von knirschenden Scherben und auf dem Boden verstreuten Aktenordnern steht ein gebeugter, blasser Mann mittleren Alters. Sein Schlips ist gelockert, ein Hemdzipfel hängt aus der Hose. Er wirkt abgespannt, gestresst und verzweifelt, während er in dem verwüsteten Raum hin und her geht. Ab und zu starrt der Mann auf die tapezierten Wände, die mit angehefteten Zeitungsartikeln und handschriftlichen Notizen übersät sind.","sz":9.0,"box":[62.4,323.5,278.4,494.5],"p":216,"i":4,"sec":"kanzlei-clarke"},{"t":"p","x":"Die Kanzlei Clarke befindet sich im zweiten Stock eines Wohngebäudes. Die Gründerin, <b>Jackie Clarke</b>, war eine unermüdliche Anwältin und Aktivistin, der wirklich etwas an Wildknock lag und die aufgrund ihrer Pro-Bono-Arbeit beliebt war. Da sie die gewaltsame Übernahme des Gebiets durch Rice Immobilien ahnte, begann Clarke, frühere und aktuelle Aktionen des Unternehmens zu untersuchen. Als sie das Muster erkannte, versuchte sie mit Hilfe von <b>Alex Penn,</b> ihres Assistenten, die Immobilienhaie mit allen rechtlichen Mitteln zu stoppen.","sz":9.5,"box":[53.9,503.5,283.8,638.0],"p":216,"i":5,"sec":"kanzlei-clarke"},{"t":"p","x":"Als Clarke zu nervig wurde, schickte Eva Schläger:innen los, um die Anwältin einzuschüchtern, indem sie die Kanzlei verwüsteten. Doch das brachte Jackie Clarke noch mehr auf die Palme. Überzeugt von ihrer Sache ging sie zum Hauptquartier von <u>Rice Immobilien</u> in der Innenstadt und konfrontierte Eva mit allen belastenden Beweisen. Eva erkannte, dass sie die furchtlose Clarke nicht terrorisieren konnte, entführte sie und brachte sie in die <u>Grabhöhle</u> unter dem Feenring- Spielplatz, wo Jackie durch den Wendigo den Tod fand.","sz":9.5,"box":[53.9,646.7,286.2,768.7],"p":216,"i":6,"sec":"kanzlei-clarke"},{"t":"sh","x":"<b>IM GESPRÄCH MIT ALEX PENN</b>","sz":10.0,"box":[309.4,62.8,475.9,72.8],"p":216,"i":7,"sec":"kanzlei-clarke"},{"t":"p","x":"Seit dem Verschwinden Jackie Clarkes vor einer Woche versucht Alex, das Büro wieder in Ordnung zu bringen. Allerdings ist er <t>verzweifelt 3</t> und nicht in der Lage, irgendetwas Sinnvolles zu tun. Ein Gespräch mit Penn könnte viel ergiebiger sein, wenn er sich beruhigt (dabei wird er Hilfe brauchen), denn er kann dem Team helfen, einige Beweise zusammenzufügen.","sz":9.5,"box":[309.0,78.3,540.8,162.8],"p":216,"i":8,"sec":"kanzlei-clarke"},{"t":"card","x":"<b><u>Rice Immobilien</u> kauft Wildknock auf. Angesichts des raubgierigen Rufs der Firma hat Jackie versucht, sie aufzuhalten.</b> Das Unternehmen hat Häuser im Viertel erworben, manchmal über Strohfirmen.","sz":null,"k":"yellow","box":[309.3,171.1,541.7,242.5],"p":216,"i":9,"sec":"kanzlei-clarke"},{"t":"card","x":"<b>Die Bewohner:innen ziehen massenweise weg und verkaufen ihr Eigentum an Rice Immobilien und Tochtergesellschaften.</b> Der juristische Kampf wird immer härter, da die Flüchtenden darauf erpicht sind, rechtzeitig zu verkaufen und sich wenig um das Schicksal des Viertels kümmern.","sz":null,"k":"yellow","box":[309.3,251.7,541.7,347.9],"p":216,"i":10,"sec":"kanzlei-clarke"},{"t":"card","x":"Wenn Alex sein Gedächtnis anstrengt (was wegen des Nebels nicht einfach ist), wird er sich erinnern, <b>dass alles mit einer Welle von Menschen begann, die das Viertel über Nacht verließen und praktisch verschwanden (Evas Opfer).</b> Gerüchte über Serienmörder:innen, Entführungen und Gewaltverbrechen – zuletzt im <u>Chicken &amp; Egg Food Truck</u> – ließen den Wert des Viertels weiter sinken.","sz":null,"k":"yellow","box":[309.3,357.1,541.7,478.4],"p":216,"i":11,"sec":"kanzlei-clarke"},{"t":"card","x":"<b>Jackie war überzeugt, dass Rice Immobilien Wildknock mutwillig entwertet.</b> Das Unternehmen hat gekaufte Häuser so vernachlässigt, dass sie jetzt unbewohnbar sind. Jackie sah darin den Hauptgrund für den Wegzug der Anwohner:innen.","sz":null,"k":"yellow","box":[309.3,487.6,541.7,571.4],"p":216,"i":12,"sec":"kanzlei-clarke"},{"t":"card","x":"<b>Letzte Woche verwüsteten Schläger:innen das Büro, offenbar eine Warnung von Rice Immobilien.</b> Sie hinterließen auf dem Schreibtisch eine angekokelte Kopie der gerichtlichen Vorladung, die Clarke Eva Rice zugestellt hatte.","sz":null,"k":"yellow","box":[309.3,580.6,541.7,652.0],"p":216,"i":13,"sec":"kanzlei-clarke"},{"t":"card","x":"<b>Clarkes stärkste Verbündete in ihrem Vorgehen gegen Rice Immobilien war Pfarrerin Williams von der <u>Kirche des Heiligen Geistes.</u></b> Williams setzte sich mit Clarke in Verbindung, nachdem die Kanzlei begonnen hatte, sich umzuhören und Klagen gegen Rice Immobilien und ihre Tochtergesellschaften einzureichen.","sz":null,"k":"yellow","box":[309.3,661.0,541.7,757.4],"p":216,"i":14,"sec":"kanzlei-clarke"}],"size":[595.276,841.89]},"217":{"tab":"","blocks":[{"t":"card","x":"<b>Jackie hat Luis Navarro als Privatdetektiv angeheuert, um den Fall Rice Immobilien zu untersuchen.</b> Er hat hart daran gearbeitet, aber Jackies Verschwinden machte seine Ermittlungen zur Obsession, und Alex hat ihn seitdem nicht mehr gesehen. Einige der Beweise befinden sich wahrscheinlich noch in seinem Haus <u>(Zuhause der Navarros).</u>","sz":null,"k":"yellow","box":[54.1,54.1,286.6,163.0],"p":217,"i":0,"sec":"kanzlei-clarke"},{"t":"sh","x":"<b>DURCHSUCHUNG DES BÜROS</b>","sz":10.0,"box":[54.3,175.4,211.2,185.4],"p":217,"i":1,"sec":"kanzlei-clarke"},{"t":"p","x":"Das Büro ist ein einziges Chaos, jemand ist augenscheinlich eingebrochen und hat es verwüstet. Die Glastür ist von außen eingeschlagen. Schreibtisch und die Stühle wurden mit einem Baseballschläger zertrümmert. Zeitungen und Notizen wurden von der Wandtafel gerissen und der Aktenschrank umgestoßen, so dass sein Inhalt auf dem Boden verstreut ist. <i>Unordnung</i> erschwert das Aufstöbern relevanter Beweise.","sz":9.5,"box":[53.9,191.0,281.4,300.5],"p":217,"i":2,"sec":"kanzlei-clarke"},{"t":"p","x":"<b>Die Durchsuchung des Büros kann zusätzliche Hinweise darauf liefern, womit Clarke befasst war.</b> Es gibt viele Artikel über die Kriminalität im Viertel sowie Notizen zu Verträgen und Transaktionen zwischen Rice Immobilien und anderen Maklerfirmen in Wildknock, die eine alternative Möglichkeit bieten, die oben aufgeführten Hinweise zu bekommen.","sz":9.5,"box":[53.9,309.3,286.3,393.7],"p":217,"i":3,"sec":"kanzlei-clarke"},{"t":"p","x":"<b>Außerdem gibt es im Büro Hinweise auf die Entführung,</b> bei der Eva spät in der Nacht das Büro betrat, sich in den Wendigo verwandelte, die Anwältin bewusstlos schlug und über die Feuerleiter entführte.","sz":9.5,"box":[53.9,402.5,286.3,449.4],"p":217,"i":4,"sec":"kanzlei-clarke"},{"t":"card","x":"<b>Jemand oder etwas hat Jackie Clarke aus ihrem Büro entführt.</b> • Auf dem Sofa liegt ein blutiger Fetzen eines Tweed-Schals, und Alex Penn kann bestätigen, dass er Clarke gehörte. Es sieht aus, als hätte ihn jemand mit großer Kraft zerrissen. • Das Fenster ist von innen eingeschlagen. • Im Parkett sind seltsame Kratzer. Sie könnten von den Krallen eines Tieres stammen. • Auf einigen der verstreuten Papiere ist Blut zu sehen. Die Entführung fand nach dem Einbruch statt. Spurenlesen oder Wahrsagen führt zur <u>Grey Alley,</u> der Abkürzung, die Eva zur <u>Grabhöhle</u> genommen hat.","sz":null,"k":"yellow","box":[54.1,460.2,286.6,662.1],"p":217,"i":5,"sec":"kanzlei-clarke"},{"t":"card","x":"Versierte Ermittler:innen, die das von Jackie Clark gesammelte Material durchgehen, können die wiederkehrende Strategie von Rice Immobilien bei der Übernahme von Stadtteilen erkennen (s. S. Aufstieg auf der Immobilienleiter, S. 210) und feststellen, <b>dass sie immer mit einer Welle von Vermisstenfällen beginnt</b>.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,163.0],"p":217,"i":6,"sec":"kanzlei-clarke"},{"t":"p","x":"Wenn Rice Immobilien ein Stadtviertel kauft und verkauft und seine Bewohner:innen es verlassen, geht es schließlich in der Enklave Albion auf. (Für Evas Heimatstadtteil Fritzberg gilt das nicht.)","sz":10.0,"box":[317.5,177.7,531.4,237.7],"p":217,"i":7,"sec":"kanzlei-clarke"},{"t":"p","x":"(Wenn du Vince Beaumont schon früh in diesen Fall verwickeln willst:) Beaumont hat die Schläger:innen auf Evas Bitte hin geschickt. <b>Jenseits des Nebels</b> gibt es eine Spur des ritterlichen Mythos der Fahrenden in Form eines flatternden Banners und von Fanfarenstößen. Ihr König hat sie auf eine Queste geschickt.","sz":10.0,"box":[317.5,258.2,529.2,343.2],"p":217,"i":8,"sec":"kanzlei-clarke"},{"t":"h","x":"KIRCHE DES HEILIGEN GEISTES","sz":16.0,"box":[334.8,372.9,538.8,388.9],"p":217,"i":9,"skip":true,"sec":"kirche-des-heiligen-geistes"},{"t":"ro","x":"Wenn man die Kirche des Heiligen Geistes in Wildknock betritt, fühlt man sich beschützt, wie in einem sicheren Hafen. Es ist ein bescheidenes, spärlich beleuchtetes und ruhiges Gebäude. Der ätherische Geruch von Weihrauch liegt in der Luft. Es scheint, als hätten Bilder und Laute der Außenwelt hier keinen Zutritt. Man hört nur das leise Echo der Schritte der wenigen Besucher, die langsam über den Steinboden schreiten.","sz":9.0,"box":[317.5,391.3,538.9,508.3],"p":217,"i":10,"sec":"kirche-des-heiligen-geistes"},{"t":"p","x":"Die Kirche des Heiligen Geistes ist einer der wenigen Orte in diesem Viertel, an dem die Menschen noch etwas Ruhe finden können. <b>Pfarrerin Keisha Williams</b> (Ala, Igbo-Gottheit der Moral, Gemeinschaft und der Seelen der Toten), eine starke, große, einfühlsame Frau, die es auf sich genommen hat, die Gemeinde durch diese schweren Zeiten zu führen, leitet dieses kleine Gotteshaus.","sz":9.5,"box":[309.0,517.3,541.3,614.3],"p":217,"i":11,"sec":"kirche-des-heiligen-geistes"},{"t":"p","x":"Als Riss Alas ist Williams in der Lage, Verstöße gegen gesellschaftliche Tabus in ihrer Gemeinde intuitiv zu spüren, auch wenn sie nicht sagen kann, was und wen genau es betrifft. Dies äußert sich gegenwärtig in einer Ahnung von Unheil, ausgelöst durch den Kannibalismus der Wendigos. Sie kann mit Toten kommunizieren (hier mit mit dem Geist von Privatdetektiv <b>Luis Navarro</b>), aber da sie eine Berührte ist, zögert sie und konzentriert sich auf die irdischen klerikalen Pflichten.","sz":9.5,"box":[309.0,622.9,541.2,732.4],"p":217,"i":12,"sec":"kirche-des-heiligen-geistes"}],"size":[595.276,841.89]},"218":{"tab":"","blocks":[{"t":"p","x":"In letzter Zeit ist die Not der Menschen in Wildknock so groß, dass sie befürchtet, dass, wenn sich nichts ändert, bald nichts mehr zu retten sein wird. Daher ist Williams bereit, alle Informationen über die jüngsten Ereignisse weiterzugeben.","sz":9.5,"box":[53.9,59.9,281.4,119.4],"p":218,"i":0,"sec":"kirche-des-heiligen-geistes"},{"t":"p","x":"Nur, wenn das Team ihr Vertrauen gewinnt, wird sie erklären ein Riss zu sein. In Wildknock spricht sich alles schnell herum, so dass jede Handlung des Teams und alle lokalen Kontaktpersonen schnell bekannt werden. Sobald sich die Pfarrerin eine positive Meinung über das Team gebildet hat, wird sie die durch ihre Mythos- Kräfte erhaltenen Informationen weitergeben.","sz":9.5,"box":[53.9,128.1,285.8,212.6],"p":218,"i":1,"sec":"kirche-des-heiligen-geistes"},{"t":"card","x":"<b>Etwas Böses hat in Wildknock Wurzeln geschlagen.</b> Zu viele Mitglieder der Gemeinde haben die Pfarrerin um Hilfe gebeten, weil ihre Angehörigen verschwunden sind. Sie hat das Bewusstsein ihrer Schäfchen für die Situation im Viertel geschärft und die Menschen dazu angehalten, immer in Gruppen unterwegs zu sein und etwas zur Verteidigung dabei zu haben.","sz":null,"k":"yellow","box":[54.1,222.0,286.6,343.3],"p":218,"i":2,"sec":"kirche-des-heiligen-geistes"},{"t":"card","x":"Ein oder zwei Wochen nach jedem Verschwinden <b>gehen die meisten Menschen, die jemanden verloren haben, davon aus, dass ihre Lieben sie und die Stadt verlassen haben.</b> (Das Werk des Nebels.)","sz":null,"k":"yellow","box":[54.1,352.5,286.6,423.9],"p":218,"i":3,"sec":"kirche-des-heiligen-geistes"},{"t":"card","x":"<b>Das Viertel stirbt langsam, fräße etwas es bei lebendigem Leibe auf.</b> Einige verschwanden, andere gingen auf die Suche nach ihnen, und wieder andere fliehen aus Angst vor Gangs und Schläger:innen. Dies führt zu einem Teufelskreis, in dem immer mehr Bewohner:innen verkaufen oder wegziehen, weil Wildknock rapide zu verfallen scheint.","sz":null,"k":"yellow","box":[54.1,433.2,286.6,542.0],"p":218,"i":4,"sec":"kirche-des-heiligen-geistes"},{"t":"card","x":"<b>Eine der Vermissten ist Mia Gupta, die Köchin des <u>Chicken &amp; Egg Food Trucks.</u></b> Vor ein paar Tagen suchte sie Hilfe. Die Köchin war bleich und verängstigt und erzählte, <b>sie habe ein Monster gesehen, das durch die Straßen von Wildknock schlich.</b> Es hatte blutüberströmte Reißzähne und lange, skelettartige Klauen. Mia vermutete, dass dieses Wesen für die Vermissten in Wildknock verantwortlich war. Einen Tag später war auch die Köchin verschwunden.","sz":null,"k":"yellow","box":[54.1,551.2,286.6,697.5],"p":218,"i":5,"sec":"kirche-des-heiligen-geistes"},{"t":"card","x":"<b>Williams’ engste Verbündete war bis zu ihrem Verschwinden vor einer Woche die Anwältin Jackie Clarke <u>(Kanzlei Clarke).</u></b> Clarke hatte die Theorie, dass Rice Immobilien die jüngste Abwanderungswelle aus der Nachbarschaft eingefädelt hatte, und, dass die „Verschwundenen“ Bewohner:innen sind, die wegzogen, nachdem das Unternehmen sie schikaniert oder bestochen hatte.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,175.4],"p":218,"i":6,"sec":"kirche-des-heiligen-geistes"},{"t":"card","x":"Gestern hat Pfarrerin Williams aus Verzweiflung versucht, mit dem Geist von Mia Kontakt aufzunehmen. Das gelang ihr nicht (Mia lebt noch), aber sie sah <b>den Geistes Luis Navarros in der <u>Grey Alley.</u></b> Die Beschreibung kann mit der Pfarrerin, Alex Penn oder Otto Scholz <u>(Chicken &amp; Egg Food Truck)</u> abgeglichen werden und zum <u>Zuhause der Navarros</u> führen.","sz":null,"k":"yellow","box":[309.3,184.6,541.7,293.5],"p":218,"i":7,"sec":"kirche-des-heiligen-geistes"},{"t":"h","x":"CHICKEN &amp; EGG FOOD TRUCK","sz":16.0,"box":[334.8,314.8,532.0,330.8],"p":218,"i":8,"skip":true,"sec":"chicken-egg-food-truck"},{"t":"ro","x":"Der Chicken &amp; Egg Food Truck hat schon bessere Tage gesehen, denn er steht mitten auf einem leeren Parkplatz. Alte Zeitungen und leere Getränkebecher liegen um die Räder verstreut. Ein paar Klappstühle laden zum Verweilen ein, doch es scheint, als würden die wenigen Gäste hier lieber ihre Bestellung schnappen und schnell wieder gehen.","sz":9.0,"box":[317.5,333.2,538.9,428.6],"p":218,"i":9,"sec":"chicken-egg-food-truck"},{"t":"p","x":"Der Chicken &amp; Egg Food Truck ist ein Schnellimbiss, der den Bewohner:innen Wildknocks Brathähnchen und Speisen im Diner-Stil serviert. Es ist der Arbeitsplatz der einzigen lebenden Person, die den Wendigo gesehen hat, <b>Mia Gupta</b>. Sie wurde entführt und in die <u>Grabhöhle</u> gebracht.","sz":9.5,"box":[309.0,437.6,539.9,509.6],"p":218,"i":10,"sec":"chicken-egg-food-truck"},{"t":"p","x":"Der Imbisswagen gehört <b>Otto Scholz</b> (Schläfer), einem netten, unkomplizierten Mann mittleren Alters, der ein breites Grinsen im Gesicht und eine fleckige Schürze um den dicken Bauch trägt. Otto ist besorgt über Mias Verschwinden und den Mangel an Kunden, also unterstützt er die Ermittlungen, so gut er kann.","sz":9.5,"box":[309.0,518.2,540.5,590.2],"p":218,"i":11,"sec":"chicken-egg-food-truck"}],"size":[595.276,841.89]},"219":{"tab":"","blocks":[{"t":"card","x":"<b>Zu viele Menschen sind in Wildknock verschwunden.</b> Anfangs gab es Gerüchte über Leute, die mit Liebhaber:innen durchbrennen, wegen Schulden die Stadt verlassen und Jugendliche, die von zu Hause weglaufen. Jetzt gibt es Gerüchte über einen Serienmörder, der durch die Straßen streift, aber Otto hielt das für eine Übertreibung – bis Mia verschwand.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,163.0],"p":219,"i":0,"sec":"chicken-egg-food-truck"},{"t":"card","x":"<b>Ehe sie verschwand, behauptete Mia, sie habe einen Mord auf der Straße beobachtet:</b> einen Ritualmörder mit einem riesigen Tierschädel als Maske, der eine Leiche durch eine Gasse schleifte. Sie war verstört und verängstigt, und ihr Gerede bereitete den Gästen Unbehagen. Otto schlug vor, mit Pfarrerin Williams von der <u>Kirche des Heiligen Geistes</u> zu sprechen.","sz":null,"k":"yellow","box":[54.1,172.2,286.6,281.1],"p":219,"i":1,"sec":"chicken-egg-food-truck"},{"t":"card","x":"<b>Mia war eine entsetzliche Köchin.</b> Ihre Hähnchenteile waren entweder halb roh oder verbrannt, und sogar ihre Omeletts waren fettig und flüssig. Trotzdem verließen die Gäste den Truck immer zufrieden. Otto weiß, dass er das bessere Essen macht (tut er auch), aber aus irgendeinem Grund wollten die Kunden immer, dass Mia für sie kochte.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,163.0],"p":219,"i":2,"sec":"chicken-egg-food-truck"},{"t":"card","x":"<b>In der Nacht, in der Mia kurz nach Feierabend verschwand, suchte ein Ex-Polizist namens Luis Navarro nach ihr.</b> Er stellte viele Fragen zu dem, was Mia angeblich gesehen hatte. Otto sagte, er könne sie höchstwahrscheinlich einholen, und wies ihn auf die Abkürzung hin, die sie normalerweise nahm, durch die <u>Grey Alley.</u>","sz":null,"k":"yellow","box":[309.3,172.2,541.7,281.1],"p":219,"i":3,"sec":"chicken-egg-food-truck"}],"size":[595.276,841.89]},"220":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 2:","sz":14.0,"box":[309.0,61.9,377.3,75.9],"p":220,"i":0,"skip":true,"sec":"schicht-2"},{"t":"card","x":"<u>GERUCH DES HUNGERS</u>","sz":null,"k":"yellow","box":[315.1,80.6,529.6,102.8],"p":220,"i":1,"sec":"schicht-2"},{"t":"p","x":"Sobald Rice Immobilien als die Bedrohung ans Licht kommt, die über den Menschen Wildknocks schwebt, möchte das Team vielleicht im Büro der Maklerfirma auflaufen. Indes deuten die Spuren in der Gasse und die von Luis Navarro hinterlassenen Hinweise auf das übernatürliche Grauen hin, das hinter all dem steckt.","sz":13.0,"box":[309.0,115.1,539.2,244.1],"p":220,"i":2,"sec":"schicht-2"},{"t":"sh","x":"<b>DETEKTIV NAVARROS GEIST</b>","sz":10.0,"box":[309.4,259.6,464.1,269.6],"p":220,"i":3,"sec":"schicht-2"},{"t":"p","x":"Die vergebliche Bemühung der Pfarrerin, mit Mia in Kontakt zu treten, hat das Tor zwischen den Welten geöffnet, so dass Navarros Geist nun herumspukt. Er manifestiert sich stumm, eine schwach bewusste Präsenz, nicht mehr als ein kraftloser Poltergeist. Bringt man ihn näher an die Welt der Lebenden, kann er <b>deutlicher in Erscheinung treten</b> und Dinge wiederholen, die er einst gesagt oder getan hat, wie ein kaputtes Aufnahmegerät. Er wünscht sich, dem Team zeigen zu können, was er herausgefunden hat, was mit ihm geschehen ist und welche Geheimnisse er kennt.","sz":9.5,"box":[309.0,275.2,540.6,409.7],"p":220,"i":4,"sec":"schicht-2"},{"t":"p","x":"Navarros Geist kann sich nur an drei Orten manifestieren, die für ihn von emotionaler Bedeutung sind: dort, wo er mit dem Wendigo kämpfte <u>(Grey Alley),</u> in seinem Haus <u>(Zuhause der Navarros)</u> und in der <u>Grabhöhle,</u> in der er den Tod fand (Schicht 3).","sz":9.5,"box":[309.0,418.3,536.1,477.8],"p":220,"i":5,"sec":"schicht-2"},{"t":"p","x":"Während das Team die Orte untersucht, wird der Geist versuchen, Kontakt aufzunehmen, indem er Beweismaterial bewegt, Gegenstände nach den SC wirft und Buchstaben auf beschlagene Spiegel schreibt oder mit Geisterblut an die Wände malt, was das Team unbeabsichtigt verletzen oder erschrecken könnte. Wenn es den SC schwerfällt, ihn zu beschwören, lass ihn KIR- CHE buchstabieren. Pfarrerin Williams kann das Team begleiten oder über das <i>Ritual des heiligen Schoßes</i> informieren, einen afrikanischen Tanz zu Ehren Alas, mit dem man Tote beschwören kann.","sz":9.5,"box":[309.0,486.5,539.0,621.0],"p":220,"i":6,"sec":"schicht-2"}],"size":[595.276,841.89]},"221":{"tab":"","blocks":[{"t":"h","x":"EVA AUF DER PIRSCH","sz":14.0,"box":[65.2,61.2,162.1,75.2],"p":221,"i":0,"sec":"schicht-2"},{"t":"p","x":"Je länger das Team in Wildknock ist, desto größer ist die Chance, dass Eva oder ein Kontakt auf die SC aufmerksam wird. Wenn ein Teammitglied <b>Nachforschungen</b> anstellt und 7-9 würfelt, kannst du es mit als Gegenfrage nach seinem nächsten Ziel fragen. Eva erfährt die Antwort. Das Gleiche passiert, wenn das Team sich ohne <b>Heimlichkeit</b> im Viertel bewegt.","sz":9.0,"box":[65.2,87.7,272.6,168.7],"p":221,"i":1,"sec":"schicht-2"},{"t":"threat","stars":"★","name":"DETEKTIV NAVARROS GEIST","spectra":"","items":[],"box":[201.6,212.2,211.8,224.2],"p":221,"i":2,"sec":"schicht-2"},{"t":"p","x":"Um dem Geist bei der <i>Manifestation</i> zu helfen, können die SC Mythos-Kräfte einsetzen, ein von Pfarrerin Williams erwähntes Ritual durchführen oder versuchen, eine starke emotionale Reaktion hervorzurufen. Wenn <i>Manifestation</i> an einem Ort den Maximalwert erreicht, haben die SC eine Vision, die „Aufzeichnung“ der vergangenen Handlungen Navarros an diesem Ort. Um die Handlungen an anderen Orten zu sehen, müssen sie dorthin gehen und die Beschwörung wiederholen, aber nicht erneut den Maximalwert für <i>Manifestation</i> erreichen.","sz":9.0,"box":[62.4,235.3,277.6,364.3],"p":221,"i":3,"sec":"schicht-2"},{"t":"p","x":"Als Gegensatz dient das <i>Bannen</i>-Spektrum des Geistes für einen einzigen Ort oder eine Szene. Wenn man ihn <i>bannt</i>, hat er dort keinen Einfluss mehr, kann aber woanders auftauchen (es sei denn, man hat ihn auch dort <i>gebannt</i>). Technisch gesehen ist der Geist eine Beschwörung durch die Kräfte der Pfarrerin. Navarro ist tot und verschwunden, und mit ihm seine Kräfte.","sz":9.0,"box":[62.4,373.3,277.2,454.3],"p":221,"i":4,"sec":"schicht-2"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN – / BAN- NEN 3 / MANIFESTATION 3</b>","sz":12.0,"box":[62.4,464.8,270.4,488.8],"p":221,"i":5,"sec":"schicht-2"},{"t":"p","x":"• Gegenstände auf das Team werfen, um Aufmerksamkeit zu erregen (<t>Autsch 1</t> und optional ein kostenloser Hinweis für das Opfer) • Die Türen eines Schauplatzes verschließen oder durch einen Gegenstand versperren, wenn noch wichtige Hinweise zu finden sind (<t>eingesperrt 3</t>) • Versuchen, in Erscheinung zu treten, was aber nur zu Stöhnen, Wehklagen und flackerndem Licht führt, oder Buchstaben auf Oberflächen erscheinen lassen, die Z-U-H-A-U-S-E oder H-E-R-Z ergeben (was wahlweise <t>besorgt 1</t> oder <t>Angst 2</t> hervorruft) • Medien, die mit ihm in Kontakt treten, auslaugen (verbrennt 1 Stärke zu Kommunikation mit Toten)","sz":9.0,"box":[62.4,493.3,274.6,646.3],"p":221,"i":6,"sec":"schicht-2"},{"t":"p","x":"• Ein von SC betrachtetes Objekt an einem anderen Ort platzieren • Ein Objekt verschieben, als bewege es sich selbst • Ein langes Knarren ertönen lassen – oder war das ein Heulen?","sz":9.0,"box":[62.4,661.3,269.0,718.3],"p":221,"i":7,"sec":"schicht-2"},{"t":"h","x":"GREY ALLEY","sz":16.0,"box":[334.8,68.9,415.0,84.9],"p":221,"i":8,"skip":true,"sec":"grey-alley"},{"t":"ro","x":"Auf den ersten Blick wirkt die Gasse wie jede andere dieses verlassenen Viertels: derselbe Müllcontainer, dieselben verstreuten Kisten und dieselbe flackernde Straßenlaterne. Doch irgendetwas fühlt sich falsch an. Jeder Schritt hallt vom Kopfsteinpflaster der Gasse wider, jedes Flüstern dringt durch die Steinwände. Es ist ein seltsames, unheimliches Gefühl, als habe diese Gasse etwas Schreckliches gesehen und erinnere sich daran.","sz":9.0,"box":[317.5,87.3,533.5,204.3],"p":221,"i":9,"sec":"grey-alley"},{"t":"p","x":"Diese Gasse ist der Ort, an dem Eva Mia entführt hat. Da sie dies in ihrer Wendigo-Gestalt getan hat, deuten alle Hinweise auf die Existenz eines Monsters in Wildknock. Sobald das Team die Gasse betritt, nimmt es einen <i>schwachen, ranzigen Geruch</i> wahr. Es ist der Geruch des Hungers, den die Gewalt des Wendigo hinterlassen hat. Er behindert Versuche, <b>Sich der Gefahr zu stellen</b> gegen die Wendigo-Psychose (s. S. 213).","sz":9.5,"box":[309.0,213.3,537.4,310.4],"p":221,"i":10,"sec":"grey-alley"},{"t":"p","x":"Als der Wendigo Mia in den Hinterhalt lockte, tauchte Privatdetektiv Luis Navarro – der im Rahmen von Ermittlungen Mia suchte – rechtzeitig auf, um ihn aufzuhalten. Er konnte zwei Schüsse abgeben, ehe Eva sich gegen ihn wandte. Einer der Schüsse verfehlte das Untier, der andere traf es und fügte ihm eine Verbrennung zu, da es Silberkugeln waren. Der Wendigo konnte den Detektiv mit einer Ohrfeige außer Gefecht setzen, aber aufgrund der Schmerzen und beschloss Eva, sich später um ihn zu kümmern. Sie machte sich nicht die Mühe, den Tatort zu säubern, ehe sie mit Mia davonlief.","sz":9.5,"box":[309.0,318.9,541.4,453.4],"p":221,"i":11,"sec":"grey-alley"},{"t":"sh","x":"<b>ANHALTSPUNKTE IN DER GASSE</b>","sz":10.0,"box":[309.4,467.0,486.1,477.0],"p":221,"i":12,"sec":"grey-alley"},{"t":"card","x":"<b>Jemand hat zwei Schüsse in der Gasse abgefeuert.</b> Zwei Patronenhülsen liegen auf dem Bürgersteig. <b>Ein speziell angefertigtes silbernes Geschoss</b> ist in die Wand eingeschlagen und passt zur Hülse.","sz":null,"k":"yellow","box":[309.3,485.0,541.7,556.4],"p":221,"i":13,"sec":"grey-alley"},{"t":"card","x":"<b>Detektiv Navarro war hier.</b> Er hat seine Brieftasche verloren, in der sich sein Ausweis befindet (der zum <u>Zuhause der Navarros</u> führt). Forensiker gehen davon aus, dass er die Schüsse abgegeben und seine Brieftasche bei einem Kampf verloren hat.","sz":null,"k":"yellow","box":[309.3,565.6,541.7,649.4],"p":221,"i":14,"sec":"grey-alley"},{"t":"card","x":"<b>Mia Gupta war hier und wurde möglicherweise verletzt.</b> An der Wand, wo sie ein kleines, glänzendes Armband mit Herzanhänger, in den ihr Name eingraviert ist, verloren hat, befindet sich eine große Blutlache.","sz":null,"k":"yellow","box":[309.3,658.7,541.7,729.8],"p":221,"i":15,"sec":"grey-alley"}],"size":[595.276,841.89]},"222":{"tab":"","blocks":[{"t":"card","x":"<b>Ein wildes Geschöpf oder vielleicht ein Monster war beteiligt.</b> An den Wänden und auf dem Müllcontainer sind riesige Krallenspuren zu sehen. Außerdem liegt ein Stück seltsam klebrigen, verbrannten Fells in der Mitte der Blutlache. Vielleicht hat der Schütze die Kreatur getroffen.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,150.6],"p":222,"i":0,"sec":"grey-alley"},{"t":"card","x":"Monsterjäger und Mystiker wissen vielleicht, dass man einige übernatürliche Kreaturen – Werwölfe, Vampire, Wendigos, Feen, Hexen usw. – <b>nur mit Silberwaffen bekämpfen kann</b>.","sz":null,"k":"yellow","box":[54.1,159.6,286.6,218.6],"p":222,"i":1,"sec":"grey-alley"},{"t":"card","x":"<b>Jenseits des Nebels</b> gibt es einen Strudel restlicher Mythos-Energien, die schwer auseinanderzuhalten sind: derselbe allgegenwärtige Hunger, der die Gegend plagt (Eva Rice, <u>Rice Immobilien</u> oder die <u>Grabhöhle),</u> aber auch ein wohlwollendes Gefühl von Sättigung (Mia Gupta, die <u>Grabhöhle),</u> eine mystische Heilkraft (Detektiv Navarro, <u>Zuhause der Navarros)</u> und ein Gefühl der Ordnung zwischen Leben und Tod (Pfarrerin Williams, <u>die Kirche).</u>","sz":null,"k":"yellow","box":[54.1,227.5,286.6,361.4],"p":222,"i":2,"sec":"grey-alley"},{"t":"card","x":"<b>Mia Guptas Armband trägt einen Splitter der Macht Annapurnas</b> (ihres Mythos, der Hindu- Göttin der Ernährung) und hilft, dem Zustand Wendigo-Psychose zu widerstehen (gib dem tragenden SC ein <i>Armband der Zufriedenheit</i>).","sz":null,"k":"yellow","box":[54.1,370.7,286.6,442.1],"p":222,"i":3,"sec":"grey-alley"},{"t":"sh","x":"<b>DETEKTIV NAVARRO BESCHWÖREN</b>","sz":10.0,"box":[54.3,458.9,248.0,468.9],"p":222,"i":4,"sec":"grey-alley"},{"t":"p","x":"Der Kampf lässt sich leichter rekonstruieren, wenn man Navarros Geist hilft, sich zu manifestieren (s. S. 220). Der Geist wird den Kampf wie folgt nachspielen:","sz":9.5,"box":[53.9,474.5,280.6,509.0],"p":222,"i":5,"sec":"grey-alley"},{"t":"ro","x":"Ein Schatten verdichtet sich zu einem bläulichen Schemen, das die Gestalt eines Mannes mittleren Alters annimmt. Er scheint gestresst und in Eile zu sein, aber er nimmt keine Notiz von euch. Die schattenhafte Gestalt fordert jemandem in der Gasse auf, stehenzubleiben und zieht eine Waffe. Zwei Schüsse hallen durch die Gasse, eine der Kugeln prallt an der Hauswand ab. Der Mann hebt erschrocken den Blick und fliegt dann durch die Luft, als habe ihn etwas Großes, Schweres getroffen. Man sieht, wie die Schlüssel und die Brieftasche des Mannes aus seinem Mantel fallen, während er auf den Boden aufschlägt und verschwindet.","sz":9.0,"box":[62.4,538.8,283.8,709.8],"p":222,"i":6,"sec":"grey-alley"},{"t":"h","x":"ZUHAUSE DER NAVARROS","sz":16.0,"box":[334.8,68.9,500.7,84.9],"p":222,"i":7,"skip":true,"sec":"zuhause-der-navarros"},{"t":"ro","x":"Das Haus, in dem Luis Navarro wohnte, scheint nur noch Erinnerungen zu bergen: ein hölzernes Spielzeugauto, das ein Kind im Hof vergessen hat, ein Vermisstenposter an der Treppe des Gebäudes. Der Korridor, der zu Navarros Wohnung führt, ist von zerbrochenen Türen gerahmt, die in geplünderte Apartments führen. Doch als ihr die Tür mit dem Schild „Navarro“ erreicht, scheint euch ein ängstlicher Blick aus dem Guckloch zu verfolgen, gefolgt von einem leisen Geräusch eines Riegels, der vorgeschoben wird.","sz":9.0,"box":[317.5,87.3,538.9,225.9],"p":222,"i":8,"sec":"zuhause-der-navarros"},{"t":"p","x":"<b>Privatdetektiv Luis Navarro</b> war ein hervorragender Polizist, den man in den Ruhestand versetzte, weil seine Kollegen ihn wegen seiner Visionen, die aus dem Mythos Gwelab’hots, eines indigenen Geistes des spirituellen Wissens und der Heilung, stammen, schikanierten. Nach der Frühpensionierung arbeitete er als Privatdetektiv. Er lebte mit seiner Frau <b>Daisy Navarro</b> (Schläferin, Ende 50) in einer Wohnung in Wildknock.","sz":9.5,"box":[309.0,234.9,540.1,331.9],"p":222,"i":9,"sec":"zuhause-der-navarros"},{"t":"p","x":"Seit Luis’ Verschwinden vor ein paar Tagen hat sich Daisy (<t>ängstlich 4</t>) in ihrer Wohnung <t>verbarrikadiert 2</t>, um sich vor den Plünder:innenbanden in Sicherheit zu bringen, und fürchtet um das Leben ihres Mannes. Wenn sie von seinem Schicksal erfährt, wird ihre Angst in <t>unkontrollierbares Schluchzen 3</t> umschlagen.","sz":9.5,"box":[309.0,340.5,540.5,412.5],"p":222,"i":10,"sec":"zuhause-der-navarros"},{"t":"p","x":"Daisy hat allen Grund, verängstigt zu sein: <b>Plünder:innen haben ein Auge auf die Wohnung geworfen</b>, in der Hoffnung, alles einsacken zu können, was noch von Wert im Gebäude ist. Wenn das Team nicht diskret ist, wird während des Besuchs eine Handvoll raubgieriger Plünder:innen (s. S. 224) auftauchen.","sz":9.5,"box":[309.0,421.2,541.4,493.2],"p":222,"i":11,"sec":"zuhause-der-navarros"},{"t":"p","x":"Zur gleichen Zeit ist der <b>Geist Luis Navarros</b> (s. S. 220) anwesend und versucht, die SC in sein Amtszimmer zu führen. Der Geist ist sich nur vage bewusst, dass es außer dem Team und seiner Frau noch andere Personen gibt. Wenn die Plünder:innen die Wohnung stürmen, wird er weiter wie ein Poltergeist agieren und die ohnehin angespannte Situation anheizen. Sollte Daisy in Gefahr geraten, wird sich die Präsenz gegen die Angreifer:innen wenden. Sollte sie sterben, erfüllt die <t>überwältigende Trauer 4</t> des Geistes den Raum.","sz":9.5,"box":[309.0,501.9,540.2,623.9],"p":222,"i":12,"sec":"zuhause-der-navarros"},{"t":"sh","x":"<b>IM GESPRÄCH MIT DAISY NAVARRO</b>","sz":10.0,"box":[309.4,637.5,503.5,647.5],"p":222,"i":13,"sec":"zuhause-der-navarros"},{"t":"card","x":"<b>Daisy Navarro hat Luis seit Tagen nicht mehr gesehen,</b> ist außer sich vor Sorge und befürchtet das Schlimmste. Sie weiß, dass Luis im Auftrag der <u>Kanzlei Clarke</u> gegen <u>Rice Immobilien</u> ermittelte und befürchtet, <b>dass er auf Vertuschungen gestoßen ist und man ihn zum Schweigen gebracht hat.</b>","sz":null,"k":"yellow","box":[309.3,654.3,541.7,750.8],"p":222,"i":14,"sec":"zuhause-der-navarros"}],"size":[595.276,841.89]},"223":{"tab":"","blocks":[{"t":"card","x":"<b>Das letzte Mal hat sie ihren Mann vor ein paar Nächten gesehen</b> (in der Nacht, in der Mia Gupta verschwand). Er wirkte verwirrt, und sie befürchtete, er hätte eine Gehirnerschütterung, <b>aber er bestand darauf, dass er los müsse, um „diesen Wahnsinn zu beenden“</b>. Er sagte, wenn ihm etwas zustoße, solle sie die Polizei auf den Feenring-Spielplatz (die <u>Grabhöhle)</u> hinweisen, aber man ignorierte sie.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,175.4],"p":223,"i":0,"sec":"zuhause-der-navarros"},{"t":"card","x":"In Erinnerungen schwelgend erzählt Daisy, dass <b>Luis sich in der Vergangenheit schon häufiger in ähnliche Schwierigkeiten gebracht hat</b>. Er steckte seine Nase immer in fremde Angelegenheiten und stieß auf die unerwartetsten Beweise. Tiere liebten ihn, Menschen fanden ihn seltsam. Er konnte Migräne oder Husten lindern, indem er sie berührte oder ihr Kräutermedizin verabreichte, obwohl sie nie wusste, wo er das gelernt hatte, da er die meiste Zeit des Lebens Polizist war.","sz":null,"k":"yellow","box":[54.1,184.6,286.6,330.9],"p":223,"i":1,"sec":"zuhause-der-navarros"},{"t":"card","x":"Die Ermittlungen gegen Rice Immobilien forderten in den letzten Wochen ihren Tribut. <b>Luis nannte das Unternehmen ein „Monster“ und hatte Albträume von einem Ungeheuer, das die Stadt verschlingt.</b> Er bat Daisy, zu ihrem eigenen Schutz eine Waffe zu tragen.","sz":null,"k":"yellow","box":[54.1,340.1,286.6,423.9],"p":223,"i":2,"sec":"zuhause-der-navarros"},{"t":"sh","x":"<b>DURCHSUCHUNG VON NAVARROS BÜRO</b>","sz":10.0,"box":[54.3,439.1,270.4,449.1],"p":223,"i":3,"sec":"zuhause-der-navarros"},{"t":"card","x":"<b>Die an die Wand gepinnten Hinweise im Büro des Detektivs deuten darauf hin, dass Mia Gupta in der Nähe des Feenring-Spielplatzes etwas Wichtiges gesehen hat.</b> Auf eine große Karte hat er ein Bild des <u>Chicken &amp; Egg Food Trucks</u> neben dem Feenring-Spielplatz (der <u>Grabhöhle)</u> gepinnt. Daneben steht: „Mia sollte es nicht sehen!“. Die Mitte des Feenring-Spielplatzes ist mit einem roten X markiert.","sz":null,"k":"yellow","box":[54.1,454.5,286.6,576.0],"p":223,"i":4,"sec":"zuhause-der-navarros"},{"t":"card","x":"Ein im Büro befindlicher Bauplan des Einkaufszentrums, das über dem Feenring-Spielplatz (der <u>Grabhöhle)</u> entstehen soll, zeigt, dass <b>Navarro das Center für eine Tarnung hielt</b>. Daran klebt eine Haftnotiz: „Clarke sagt, das Projekt ist nicht rentabel. Warum hier?“ Beim genaueren Umsehen stößt man auf ein topografisches Gutachten, das besagt, dass jedes Bauvorhaben auf dem Park wegen einer instabilen Höhle darunter gefährlich ist.","sz":null,"k":"yellow","box":[54.1,584.9,286.6,718.8],"p":223,"i":5,"sec":"zuhause-der-navarros"},{"t":"card","x":"<b>Navarro war besessen vom Bild eines Monsters.</b> Die Wände seines Büros sind mit fiebrigen Zeichnungen eines hageren, menschenähnlichen Wesens bedeckt, dessen vertrocknete Haut sich straff über die Knochen spannt. Der Kopf sieht aus wie ein Hirschschädel, aus dessen Maul scharfe Zähne ragen.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,150.6],"p":223,"i":6,"sec":"zuhause-der-navarros"},{"t":"card","x":"<b>Navarro besitzt einen Vorrat an Silberwaffen.</b> Die Schreibtischschublade enthält ein <i>silbernes Messer</i>, einen <i>.44 Magnum-Revolver</i> und speziell angefertigte .<i>44 Magnum-Silberkugeln</i>. Daisy Navarro fügt hinzu, ihr Mann habe sie angefleht, die zweite Waffe zu tragen, aber sie konnte sich nicht vorstellen, sie zu benutzen.","sz":null,"k":"yellow","box":[309.3,159.6,541.7,256.0],"p":223,"i":7,"sec":"zuhause-der-navarros"},{"t":"card","x":"Monsterjäger:innen, Kryptozoolog:innen oder SC mit Kenntnis übernatürlicher Überlieferungen können die Kreatur als <b>Wendigo</b> identifizieren, einen bösen Geist, der aus großem Hunger entsteht, meist während eines strengen Winters. <b>Den Wendigo kann man nur mit Feuer oder Silber verletzen.</b>","sz":null,"k":"yellow","box":[309.3,265.2,541.7,361.4],"p":223,"i":8,"sec":"zuhause-der-navarros"},{"t":"sh","x":"<b>DETEKTIV NAVARRO BESCHWÖREN</b>","sz":10.0,"box":[309.4,383.8,503.1,393.8],"p":223,"i":9,"sec":"zuhause-der-navarros"},{"t":"p","x":"Die Hinweise im Büro findet man leichter, wenn man Navarros Geist hilft, sich zu manifestieren (s. S. 220). Der Geist wird Navarros verzweifelte Spurensuche wie folgt nachstellen:","sz":9.5,"box":[309.0,399.4,537.0,446.4],"p":223,"i":10,"sec":"zuhause-der-navarros"},{"t":"ro","x":"Ein Windstoß weht in den Raum, gefolgt vom Geräusch schwerer Schritte. Dann erscheint die Silhouette Luis Navarros in der Türöffnung. Ihr seht seine müden Augen und sein unrasiertes Gesicht, als er eilig an euch vorbeigeht. Dann bemerkt ihr, dass er aufgerollte Plakate unter dem Arm trägt, die er entrollt und an die Wand heftet. Mit triumphierender Geste schreibt er etwas auf ein Foto, heftet es an eines der Plakate und geht zu einer Landkarte hinüber, auf der er ein rotes X markiert. Nachdem er eine Weile darauf gestarrt hat, wird sein Blick entschlossen. Privatdetektiv Navarros Geist holt einen 44er Magnum-Revolver aus der Schreibtischschublade. Es scheint, als sähe er euch direkt an, während er die Waffe langsam und bedächtig lädt. „Hoffen wir, dass sie nicht daheim ist.“ Er stöhnt, während er die Waffe in ein Holster unter seinem Mantel steckt, durch die Tür geht und verschwindet.","sz":9.0,"box":[317.5,479.0,538.9,725.6],"p":223,"i":11,"sec":"zuhause-der-navarros"}],"size":[595.276,841.89]},"224":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"RAUBGIERIGE PLÜNDER:INNEN (+ )","spectra":"","items":[],"box":[215.4,56.7,257.6,68.7],"p":224,"i":0,"sec":"zuhause-der-navarros"},{"t":"p","x":"Die kleine Gruppe von Abschaum (Größenfaktor 1) ist der Wendigo-Psychose zum Opfer gefallen und nutzt die Situation in Wildknock, um verlassene und manchmal bewohnte Häuser auszuräumen. Sie sind wie Stadtstreicher:innen oder Überlebende einer Apokalypse in zerfledderte Outdoor-Kleidung gekleidet: Wollmützen, Anglerwesten, blutverschmierte Mäntel und schlammverschmierte Wanderstiefel, die sie in mehreren Schichten tragen, als wollten sie sich vor einer schrecklichen Kälte schützen. Sie scheinen am Verhungern zu sein und könnten bald dem wahnsinnigen kannibalischen Drang des Wendigo erliegen.","sz":9.0,"box":[62.4,79.9,276.6,220.9],"p":224,"i":1,"sec":"zuhause-der-navarros"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 3 / PSY- CHOSE UMKEHREN 3 / HUNGER TEMPORÄR STILLEN 3 / ERLIEGEN 3 / VERHUNGERN 5</b>","sz":12.0,"box":[62.4,231.4,274.5,267.4],"p":224,"i":2,"sec":"zuhause-der-navarros"},{"t":"p","x":"• <b>Durchdrehen</b>: Gib den Raubgierigen Plünder:innen als weiche Aktion <t>dem Hunger Erliegen 1</t>. • <b>Abstieg in den Kannibalismus +</b>★: Erhöhe einmal pro Gruppe, wenn <i>Erliegen</i> den Maximalwert erreicht, die Maximalwerte aller Plünder:innen und die Effekte der harten Aktionen um 1 und führe eine harte Aktion gegen einen SC oder NSC aus.","sz":9.0,"box":[62.4,271.9,276.1,352.9],"p":224,"i":3,"sec":"zuhause-der-navarros"},{"t":"p","x":"• Eine verschlossene Tür aufbrechen oder einschlagen oder ein Hindernis aus dem Weg räumen (<b>Die Dinge richtig kompliziert machen</b> oder eine behindernde Stärke/Zustand verbrennen) • Jemanden mit einem Brecheisen, einer Axt oder Hacke angreifen (<t>offene Wunde 2</t>) • Sich auf jemanden stürzen und ihn beißen (<t>Bisswunde 2</t> und <t>dem Hunger Erliegen 1</t>)","sz":9.0,"box":[62.4,361.9,271.2,454.9],"p":224,"i":4,"sec":"zuhause-der-navarros"},{"t":"p","x":"• Näher kommen und ausschwärmen • An die Tür klopfen und in einem ängstlichen, hungrigen Ton und um Einlass bitten • Sich die Lippen lecken und jemanden anstarren, als wäre er Futter, und sichtlich mit Hunger kämpfen","sz":9.0,"box":[62.4,463.9,277.8,520.9],"p":224,"i":5,"sec":"zuhause-der-navarros"},{"t":"h","x":"RICE IMMOBILIEN","sz":16.0,"box":[334.8,68.9,454.2,84.9],"p":224,"i":6,"skip":true,"sec":"rice-immobilien"},{"t":"ro","x":"Die Büros von Rice Immobilien an der Spitze eines modernen Hochhauses mit einem wundervollen Ausblick auf die Stadt sind weiß, hell erleuchtet und steril. Hinter dem Empfangstresen befinden sich gläserne Räume, in denen fleißige Mitarbeiter:innen werkeln. Einige von ihnen telefonieren, andere legen Papiere ab, und ein Makler kommt aus einem Besprechungsraum und schüttelt einem gut gekleideten Kunden die Hand. Plakate an den Wänden zeigen lächelnde Menschen vor grünen Rasenflächen und weißen Lattenzäunen. „Haben Sie einen Termin?“, fragt die Sekretärin freundlich und schlägt bereits den Kalender auf, um nachzusehen.","sz":9.0,"box":[317.5,87.3,538.9,258.3],"p":224,"i":7,"sec":"rice-immobilien"},{"t":"p","x":"Rice Immobilien ist der Ort, an dem alle Transaktionen Evas stattfinden. Für die Mitarbeiter:innen von Rice Immobilien ist das Unternehmen Kapitalismus in Reinkultur. Zur Zeit konzentriert sich das Unternehmen auf den Erwerb und anschließenden Verkauf Wildknocks, und obwohl einige der hier arbeitenden Immobilienmakler:innen erkennen, dass Rice Immobilien das Unglück der dortigen Einwohner:innen ausnutzt, weiß niemand etwas von dem üblen Spiel hinter den Kulissen.","sz":9.5,"box":[309.0,267.3,539.3,389.3],"p":224,"i":8,"sec":"rice-immobilien"},{"t":"p","x":"<b>Mitten im Tumult steht die berühmte Immobilienmagnatin Eva Rice.</b> Attraktiv, selbstbewusst und fast omnipräsent scheint sie alle Aufmerksamkeit im Raum auf sich zu ziehen.","sz":9.5,"box":[309.0,398.1,540.1,444.9],"p":224,"i":9,"sec":"rice-immobilien"},{"t":"h","x":"MACHTSPIELCHEN","sz":14.0,"box":[319.7,470.1,407.6,484.1],"p":224,"i":10,"sec":"rice-immobilien"},{"t":"p","x":"Wenn dein Spiel eine dramatische Szene braucht, lass die SC in eine entscheidende Sitzung hineinplatzen, in der Eva versucht, den Verkauf Wildknocks an einen potenziellen Sanierer, <b>Porky Thatcher</b> von Porky &amp; Bros., einzutüten.","sz":9.0,"box":[319.7,496.7,528.3,553.7],"p":224,"i":11,"sec":"rice-immobilien"},{"t":"p","x":"Gib Thatcher das nach zwei Seiten offene Spektrum <i>Überzeugen 3</i> und lass die SC und Eva versuchen, den Investor zu überzeugen, das Viertel zu kaufen oder eben nicht. Beide Seiten können dem Investor den Zustand <t>überzeugt zu kaufen</t> bzw. <t>überzeugt nicht zu kaufen</t> verleihen. Bei dem Spektrum kann eine Seite ihren Zustand nicht zuweisen, solange es Stufen des gegnerischen gibt. Man muss zuerst 1:1 die eigenen Stufen nutzen, um gegnerische zu entfernen.","sz":9.0,"box":[319.7,562.3,528.2,679.3],"p":224,"i":12,"sec":"rice-immobilien"},{"t":"p","x":"Wenn <i>Überzeugen</i> einen Maximalwert erreicht, trifft Thatcher seine Entscheidung. Wenn er sich entscheidet, Wildknock nicht zu kaufen, wird Eva <t>aggressiv 2</t>.","sz":9.0,"box":[319.7,688.0,530.0,721.0],"p":224,"i":13,"sec":"rice-immobilien"}],"size":[595.276,841.89]},"225":{"tab":"","blocks":[{"t":"sh","x":"<b>IM GESPRÄCH MIT EVA</b>","sz":10.0,"box":[54.3,372.5,179.5,382.5],"p":225,"i":0,"sec":"rice-immobilien"},{"t":"p","x":"Es ist nicht schwer, einen Termin mit Eva Rice zu vereinbaren, solange die Sekretärin glaubt, dass man ihre Zeit nicht vergeuden wird. Das Team kann dies mit List und Tücke tun, indem es sich als Investor:innengruppe ausgibt oder gar als Anwält:innen, die Bürger:innen von Wildknock vertreten. Sie könnten (bis zu einem gewissen Grad) sogar die Wahrheit über ihre Absichten und Verdächtigungen in Bezug auf das Unternehmen oder Eva selbst sagen. Eva hat keine Angst vor einem Konflikt.","sz":9.5,"box":[53.9,388.0,285.8,510.0],"p":225,"i":1,"sec":"rice-immobilien"},{"t":"p","x":"<b>Die Immobilienmaklerin wirkt nach außen hin sehr ruhig.</b> Es ist schwer, sie aus der Ruhe zu bringen. Sie spricht mit ruhiger Stimme und erklärt alles mit sachlichen Argumenten. Meist trägt sie ein kleines Lächeln auf den Lippen, das man entweder als höflich oder als herablassend deuten kann.","sz":9.5,"box":[53.9,518.8,282.9,590.7],"p":225,"i":2,"sec":"rice-immobilien"},{"t":"p","x":"<b>Eva wird die Rolle der „bösen“(wenn auch gesetzestreuen) Baulöwin spielen</b>, um die Aufmerksamkeit von ihrem wahrhaft bösen, legendären Alter Ego abzulenken. Ihr zufolge plant sie nach dem Kauf Wildknocks, das Viertel zu sanieren. In Wildknock ist etwas Schlimmes im Gange, aber es begann lange bevor sie sich einmischte. Man kann ihr schließlich nicht vorwerfen, dass sie versucht, aus Zitronen Limonade zu machen. Sie wird bestätigen, dass Jackie Clarke ihr einen Besuch abstattete, sie beschimpfte und drohte, sowohl Eva als auch ihr Unternehmen zu verklagen. Eva begrüßte die Herausforderung und ist sicher, dass sie den Rechtsstreit gewonnen hätte.","sz":9.5,"box":[53.9,599.5,284.0,758.9],"p":225,"i":3,"sec":"rice-immobilien"},{"t":"p","x":"Sie weiß nichts von dem Einbruch bei <u>Kanzlei Clarke</u> oder Clarkes Verschwinden. <b>SC, die viele Hinweise ausgeben, können Lügen in der Geschichte sehen.</b>","sz":9.5,"box":[309.0,368.9,535.4,403.5],"p":225,"i":4,"sec":"rice-immobilien"},{"t":"card","x":"Psycholog:innen oder gute Menschenkenner:innen, die ein Persönlichkeitsprofil von ihr erstellen, werden feststellen, <b>dass die wahre Eva Rice Wildknock verschlingen will – und alles andere auch</b>. Trotz ihres ruhigen Auftretens ist sie in Wirklichkeit eine Frau, die sofortige Befriedigung all ihrer Bedürfnisse anstrebt und der es um die Macht geht, das zu bekommen, was sie will, und zwar immer.","sz":null,"k":"yellow","box":[309.3,414.7,541.7,536.3],"p":225,"i":5,"sec":"rice-immobilien"},{"t":"card","x":"<b>Jenseits des Nebels</b> herrscht in Eva eine gigantische Leere, die nichts als Hunger und Entbehrung enthält. Jeder Versuch, Evas wahre Gestalt oder Geist zu erforschen, löst ihre Spezialaktion <b>Abgrundtiefe Qualen der Entbehrung</b> aus und setzt den Geist des sie beobachtenden Risses der Wendigo-Psychose aus.","sz":null,"k":"yellow","box":[309.3,545.5,541.7,641.7],"p":225,"i":6,"sec":"rice-immobilien"},{"t":"card","x":"Eine medizinische Untersuchung, z. B. das Messen von Eva Rices Puls, ein Ultraschall oder ein Röntgenbild, würde zeigen, <b>dass sie kein Herz hat</b>. Dies kann man mit legendären Mitteln herausfinden, das kann aber die <b>Abgrundtiefen Qualen der Entbehrung</b> auslösen.","sz":null,"k":"yellow","box":[309.3,650.9,541.7,734.7],"p":225,"i":7,"sec":"rice-immobilien"}],"size":[595.276,841.89]},"226":{"tab":"","blocks":[{"t":"card","x":"<b>Wenn sie sich bedroht fühlt, versucht sie, dem Team eine Falle zu stellen</b>, indem sie es auf den Feenring-Spielplatz (die <u>Grabhöhle)</u> hinweist und behauptet, dort passiere etwas Unheimliches: Ihre Bauarbeiter:innen haben fremdartige Schreie gehört und sogar Geister gesehen.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,150.6],"p":226,"i":0,"sec":"rice-immobilien"},{"t":"sh","x":"<b>EINDRINGEN IN RICES BÜROS</b>","sz":10.0,"box":[54.3,163.4,216.3,173.4],"p":226,"i":1,"sec":"rice-immobilien"},{"t":"p","x":"Das Team könnte versuchen, sich nach Feierabend ins Büro von Rice Immobilien zu schleichen, in die Computer einzudringen oder jemanden zu überlisten, der Zugang zu Evas Büro hat (z. B. ein Reinigungsteam). Kein leichtes Unterfangen: Das Unternehmen verfügt über ein eigenes Sicherheitsteam und ein hochmodernes Sicherheitssystem mit Kameras (verwende die Bedrohungsprofile Elite-Sicherheitsleute und Alarmanlage aus dem 287). Ferner haben die Räume <i>Glaswände</i>. Wenn es dem Team gelingt, diese Probleme zu umgehen, wird es in den Archiven einige interessante Daten finden, die dazu dienen könnten, Eva und ihre Firma <i>eines Verbrechens zu bezichtigen</i>.","sz":9.5,"box":[53.9,179.0,285.1,338.5],"p":226,"i":2,"sec":"rice-immobilien"},{"t":"card","x":"Die Aufzeichnungen von Rice Immobilien <b>offenbaren die wahren Absichten in Bezug auf Wildknock</b> und die Weise, mit dem sie diese erreichen wollen (s. S. Aufstieg auf der Immobilienleiter, S.210). Die Methode ist rücksichtslos, aber nicht wirklich illegal.","sz":null,"k":"yellow","box":[54.1,349.6,286.6,433.4],"p":226,"i":3,"sec":"rice-immobilien"},{"t":"card","x":"<b>Dies ist nicht das erste Mal, dass Rice Immobilien ein Stadtviertel unter dem Deckmantel der „Stadterneuerung“ aufkauft</b>. In den letzten Jahren gab es ein halbes Dutzend Übernahmen. Keiner der Käufer:innen konnte die Sanierung leisten. In einem verborgenen Ordner befinden sich Unterlagen über das erste Projekt in einem Vorort namens <u>Fritzberg.</u>","sz":null,"k":"yellow","box":[54.1,442.7,286.6,551.5],"p":226,"i":4,"sec":"rice-immobilien"},{"t":"card","x":"Eine genaue Überprüfung von Rice Immobilien zeigt, dass jedem Kaufangebot des Unternehmens ein Entwurf vorausging. Seltsamerweise datieren die Entwürfe aus der Zeit, bevor die Probleme in Wildknock begannen. Man mag sich fragen, <b>wie Rice Immobilien den Verfall von Wildknock „ahnen“</b> konnte.","sz":null,"k":"yellow","box":[54.1,560.7,286.6,656.9],"p":226,"i":5,"sec":"rice-immobilien"},{"t":"card","x":"<b>Der Feenring-Spielplatz soll einem Einkaufszentrum weichen.</b> Das Projekt ist verdächtig unrentabel, es gibt <b>Beweise für die Vertuschung</b> der topografischen Untersuchung, die zeigte, dass der Ort aufgrund einer darunter liegenden Höhle (der <u>Grabhöhle)</u> unsicher ist.","sz":null,"k":"yellow","box":[54.1,666.1,286.6,750.0],"p":226,"i":6,"sec":"rice-immobilien"},{"t":"threat","stars":"★★★★","name":"EVA RICE","spectra":"VERLETZEN 4 / UNSCHÄDLICH MACHEN 6 / EINES VERBRECHENS BEZICHTIGEN 5","items":["<b>Unzerstörbarer böser Geist</b>: Eva Rice ignoriert körperliche Schäden, die nicht durch Feuer oder Silber entstehen.","<b>Herzlos</b>: Solange sich ihr Herz außerhalb ihres Körpers befindet, ignoriert Eva alle emotionalen Zustände (nicht aber instinktive wie Wut, Aggression oder Angst). Wenn man ihr das Herz einsetzt (vermutlich, indem man sie zuerst überwältigt), wird sie <t>von Schuld überwältigt 5</t>.","<b>Meine nächste Mahlzeit</b>: Wenn Eva Rice die Szene betritt, gib ihr <t>wachsam 3</t>, erneuerbar als weiche Aktion.","<b>Grausam</b>: Wenn man sie im Nahkampf angreift, beißt sie ihre Angreifer:in oder versucht, ihre Klauen in ihr zu versenken (<t>aufgerissen 3</t>).","<b>Beklemmend</b>: Wenn Eva Rices <i>Verletzen</i> den Maximalwert erreicht oder wenn sie es will, löst sich ihr Körper auf, und alle physischen Zustände enden. Am Ende der Szene rematerialisiert sie sich aus dem Boden, in dem ihr Herz begraben ist (dem Hinterhof von <u>Evas Elternhaus).</u>","<b>Abgrundtiefe Qualen der Entbehrung</b>: Wenn man Eva Rice <b>Jenseits des Nebels</b> betrachtet oder magisch Verstand, Herz oder Gefühle beeinflusst, ist man der Wendigo-Psychose (<t>am Verhungern 3</t>) ausgesetzt, und die erhaltenen Hinweise sind schwammig und unvollständig.","<b>Leibwächter:innen</b>: Wenn sie einen juristischen Zustand nimmt, vor dem Leibwächter:innen sie schützen können, nehmen diese ihn (s. S. 288, Firmenanwält:in).","Mit den Klauen alles zerreißen, von Fleisch bis Stein (<t>aufgerissen 4</t>) oder jemanden mit einer Hand an der Kehle packen (<t>gepackt 4</t>)","Ihre Zähne in einem hilflosen Opfer versenken (verwandelt einen <t>gepackt</t>-Status in einen <t>wilden Biss</t> der gleichen Stufe)","Die lähmende Kraft der Wendigo-Psychose auf ihr(e) Opfer fokussieren und sie flüsternd verspotten (<t>vom Hunger verzehrt 4</t> oder <t>am Verhungern 3</t> für alle Anwesenden)","Ausbrechen, eine Gebäudewand hochklettern und über die Dächer fliehen (bis zu 3 Fesselungs-Marker oder taktische Hindernisse verbrennen und dann <b>Ihnen etwas verweigern, das sie wollen</b>)","Einen teuren Anwalt beauftragen, um Klagen abzuwehren und Gegenklage zu erheben (erzeuge eine neue Bedrohung: Firmenanwält:in, s. 288)","Investoren überzeugen, ein sanierungsbedürftiges Grundstück zu kaufen (<t>überzeugt zu kaufen 2</t> und <t>diskreditiert 1</t> für etwaige Gegner:innen)","Sich in den Wendigo verwandeln oder in ihre menschliche Gestalt zurückkehren","Als Eva frostig lächeln und ruhig und logisch antworten","Als Wendigo schwer atmen und gierig sabbern"],"box":[364.0,57.0,404.8,69.0],"p":226,"i":7,"sec":"rice-immobilien"}],"size":[595.276,841.89]},"227":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 3:","sz":14.0,"box":[53.9,61.9,122.0,75.9],"p":227,"i":0,"skip":true,"sec":"schicht-3"},{"t":"card","x":"<u>HÖHLE DES MONSTERS</u>","sz":null,"k":"yellow","box":[39.2,77.5,290.0,104.3],"p":227,"i":1,"sec":"schicht-3"},{"t":"h","x":"DIE GRABHÖHLE","sz":16.0,"box":[79.7,120.8,185.7,136.8],"p":227,"i":2,"skip":true,"sec":"die-grabhoehle"},{"t":"ro","x":"Einst war der Feenring-Spielplatz ein fröhlicher Ort, den die Kinder der Gegend liebten. Jetzt liegt er verlassen da, ein einsamer Flecken inmitten einer Baustelle. Verrostete Rutschen und Karussells liegen kaputt zwischen öligen Lachen und ausgehobenen Erdhügeln. Die Luft ist seltsam kalt, und das ganze Gebiet riecht nach Verfall. Es könnte eine optische Täuschung sein, aber in der Mitte des Spielplatzes scheint ein Mann in einem Regenmantel zu stehen. Einen Moment später ist die Gestalt verschwunden. Oder ist sie in ein Erdloch gesprungen ...?","sz":9.0,"box":[62.4,139.2,283.8,288.6],"p":227,"i":3,"sec":"die-grabhoehle"},{"t":"p","x":"Eva empfindet die uralte Grabhöhle unter dem Feenring-Spielplatz als idealen Ort, um ihre Opfer im Verborgenen zu verzehren und ihre Knochen zu sammeln, ohne Verdacht zu erregen. Leider hat Mia Gupta Eva auf frischer Tat ertappt und damit gezwungen, ihre Pläne zu ändern und ein Vermögen auszugeben, um ein neues Einkaufszentrum über der Höhle zu bauen und die Beweise endgültig zu begraben. Mia ist derzeit in der Höhle gefangen, zusammen mit den Überresten Jackie Clarkes, Detektiv Navarros und dutzender weiterer Opfer aus Wildknock.","sz":9.5,"box":[53.9,297.6,286.3,432.1],"p":227,"i":4,"sec":"die-grabhoehle"},{"t":"p","x":"Sobald das Team im Park angekommen ist, führt der Geist Luis Navarros es zu einem Loch im Boden, das zur Grabhöhle führt. Der vertikale Schacht ist 15 m tief und endet in einer <i>völlig dunklen Höhle</i>.","sz":9.5,"box":[53.9,440.8,285.1,487.8],"p":227,"i":5,"sec":"die-grabhoehle"},{"t":"sh","x":"<b>IN DER HÖHLE</b>","sz":10.0,"box":[54.3,501.4,133.3,511.4],"p":227,"i":6,"sec":"die-grabhoehle"},{"t":"ro","x":"Es dauert eine Weile, bis man sich an die Dunkelheit gewöhnt hat, aber schon bald wird klar, dass die Felswände von Nischen gesäumt sind, in denen die verhüllten Überreste alter Leichname liegen. Auf die Steine sind ausgeblichene Symbole gemalt. Doch die schreckliche Erkenntnis, dass das Geräusch euer Stiefel auf dem Höhlenboden von den knackenden Knochen dutzender menschlicher Skelette stammt, drängt weitere Details in den Hintergrund.","sz":9.0,"box":[62.4,515.4,283.8,632.4],"p":227,"i":7,"sec":"die-grabhoehle"},{"t":"p","x":"Wenn Eva die SC hierhergeschickt hat, von ihren Plänen, die Höhle zu besuchen, erfahren hat oder wenn es einfach zur Spannung im Spiel passt, wird der Wendigo in der Dunkelheit lauern und auf seine Chance warten, das Team zu reißen und die Einmischung zu beenden. Er ist sich der Bedrohung des Einsturzes bewusst (er kennt die Ergebnisse der topografischen Vermessung des Einkaufszentrums), fühlt sich aber sicher und erlaubt sich, unvorsichtig zu sein.","sz":9.5,"box":[53.9,641.4,285.8,750.9],"p":227,"i":8,"sec":"die-grabhoehle"},{"t":"p","x":"Die tötungswillige Eva lässt alle Hemmungen fallen, verwandelt sich vor dem Team und könnte sogar Verbrechen zugeben, wenn man sie fragt, was später zur <i>Überführung</i> nützlich wäre. Die SC könnten sie dazu bringen zu verraten, wo sie ihr Herz vergraben hat.","sz":9.5,"box":[309.0,59.9,532.8,119.4],"p":227,"i":9,"sec":"die-grabhoehle"},{"t":"p","x":"Wenn es zum Kampf kommt und Eva gewinnt, wird sie die Teammitglieder eines nach dem anderen verschlingen, beginnend mit dem gefährlichsten, während sie die anderen mit Ketten von der Baustelle <t>angekettet 5</t> und <t>vor Hunger verrückt 3</t> werden lässt. Wenn das Team Eva vernichtet, bevor sie fliehen kann, wird sie sich im Hinterhof ihres Elternhauses rematerialisieren und den nächsten Angriff planen.","sz":9.5,"box":[309.0,128.1,540.8,225.1],"p":227,"i":10,"sec":"die-grabhoehle"},{"t":"card","x":"<b>Die Grabhöhle ist der Futterplatz des Monsters.</b> Die Gebeine in den Nischen mögen zwar uralt sein, aber die Knochen auf dem Boden haben höchstens ein paar Monate hier gelegen. Alle sind mit Nagespuren übersät. Kein einziger Fitzelchen Fleisch hängt mehr daran.","sz":null,"k":"yellow","box":[309.3,234.7,541.7,318.8],"p":227,"i":11,"sec":"die-grabhoehle"},{"t":"card","x":"<b>Die Opfer sind die vermissten Bewohner:innen Wildknocks.</b> Die Überreste eines zerrissenen Tweedschals, der zu dem von Jackie Clarke passt, sind darunter zu finden <u>(Kanzlei Clarke),</u> ebenso wie Teile von Privatdetektiv Navarros Regenmantel, die zu seinem Erscheinungsbild in den Visionen passen.","sz":null,"k":"yellow","box":[309.3,327.7,541.7,424.2],"p":227,"i":12,"sec":"die-grabhoehle"},{"t":"card","x":"<b>Die auf die Höhlenwände gemalten Piktogramme</b> erzählen die Geschichte des Wendigos und wie er Menschen vor Hunger in den Wahnsinn treibt. Sie sind als Nebenwirkung von Evas Mythos entstanden. Wer sie lange genug studiert, öffnet sich der Wendigo-Psychose (<t>am Verhungern 3</t>), entdeckt aber auch einen Abschnitt, <b>der den Wendigo zeigt, wie er sich das Herz herausreißt und es in der Erde vergräbt</b>.","sz":null,"k":"yellow","box":[309.3,433.4,541.7,567.1],"p":227,"i":13,"sec":"die-grabhoehle"},{"t":"card","x":"Graben oder Wahrsagen zeigen, dass <b>das Herz nicht in der Höhle ist</b>.","sz":null,"k":"yellow","box":[309.3,576.3,541.7,610.3],"p":227,"i":14,"sec":"die-grabhoehle"}],"size":[595.276,841.89]},"228":{"tab":"","blocks":[{"t":"p","x":"<b>Mia Gupta</b> liegt angekettet und geknebelt in einer der Nischen, wo sie tagelang ohne Nahrung und Wasser ausharren musste (obwohl sie als Riss der Nahrung ewig so überleben könnte). Sie ist <t>erschüttert 2</t> von den Erlebnissen, kann aber langsam und brüchig sprechen.","sz":9.5,"box":[53.2,385.4,284.0,444.9],"p":228,"i":0,"sec":"die-grabhoehle"},{"t":"card","x":"<b>Mia sah, wie Eva sich in den Wendigo verwandelte, bevor sie einen Mann in Wildknock tötete</b> (Mia kannte den Mann nicht). Eva sah sie und holte sie in der nächsten Nacht. Privatdetektiv Navarro versuchte, Eva abzuhalten, Mia zu entführen, was ihm jedoch nicht gelang. Eva brachte Mia in die Höhle, und diese nutzte ihre Kräfte, um Evas Hunger zu stillen und zu verhindern, dass der Wendigo sie fraß. Misstrauisch beschloss Eva, sie am Leben zu lassen. Später unternahm Navarro einen kühnen Versuch, Mia zu retten, aber Eva stürzte sich auf ihn, überwältigte ihn und verschlang den Detektiv vor Mias Augen.","sz":null,"k":"yellow","box":[54.1,452.4,286.6,636.2],"p":228,"i":1,"sec":"die-grabhoehle"},{"t":"sh","x":"<b>PRIVATDETEKTIV NAVARRO BESCHWÖ- REN</b>","sz":10.0,"box":[309.4,385.7,525.6,407.7],"p":228,"i":2,"sec":"die-grabhoehle"},{"t":"p","x":"Wenn die SC den Geist des Detektivs noch beschwören können (s. S. 220), vielleicht mit Hilfe seiner <i>Gebeine</i> und der <i>heiligen Kraft des Friedhofs</i>, wird die Erscheinung ihnen seine letzte Konfrontation mit Eva in der Höhle zeigen und auf ihr Herz in <u>Fritzberg</u> verweisen.","sz":9.5,"box":[309.0,413.3,538.8,472.8],"p":228,"i":3,"sec":"die-grabhoehle"},{"t":"p","x":"Wenn sie den Geist nicht rufen (oder als zusätzlichen Hinweis, wenn sie es tun), wird Navarros Geist die Botschaft <i>DAHEIM IST DAHEIM</i> in Blut an die Wände schreiben oder Knochen so anordnen, was das Team nach <u>Fritzberg</u> oder zu <u>Evas Luxusvilla</u> führt.","sz":9.5,"box":[309.0,481.5,539.7,541.0],"p":228,"i":4,"sec":"die-grabhoehle"},{"t":"ro","x":"Der Geist Navarros taucht wieder auf. Er kniet auf dem Boden und lädt seinen Revolver. Seine Stimme hallt im Dunkel der Höhle wider, als er vor sich hinmurmelt: „Ihr Herz muss etwas bedeuten. Ich sehe es immer wieder ... verdammte Visionen. Ist es das, was du in <u>Fritzberg</u> versteckst, du Untier?“ Plötzlich springt Navarro auf und feuert in die Leere der Höhle. Als das Klicken einer leeren Kammer zu hören ist, verfinstert sich sein Antlitz. Dann fliegt er durch die Luft und landet mit einem dumpfen Aufprall auf dem Boden. Es sieht aus, als starre er euch direkt an, wie er mit blutgetränktem Mantel auf dem Rücken liegt.","sz":9.0,"box":[317.5,573.6,538.9,744.6],"p":228,"i":5,"sec":"die-grabhoehle"}],"size":[595.276,841.89]},"229":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"EINSTÜRZENDE HÖHLE","spectra":"EINSTÜRZEN 4","items":["<b>Einsturzgefährdet</b>: Wenn jemand eine Aktion ausführt, die die Höhlenwände erheblich beschädigen könnte, erleidet die einstürzende Höhle <t>Erschütterung 1</t>. Wenn es eine <b>Mit aller Gewalt</b>- Aktion war und die Spieler:in sich nicht entschieden hat, den Kollateralschaden zu kontrollieren, erhält die einstürzende Höhle stattdessen <t>Beben 2</t>.","<b>Rennt um euer Leben</b>: Wenn <i>Einstürzen</i> den Maximalwert erreicht, müssen die SC <b>Ein Risiko eingehen</b>, um nicht <t>lebendig begraben 5</t> zu erleiden. Wenn sie es nicht schaffen, werden sie zudem <t>zerschmettert 5</t> (sie können <b>Sich der Gefahr stellen</b>, aber nicht mit den gleichen Stärken). Wenn ein SC <t>lebendig begraben</t> ist, kann die SL ihm als weiche Aktion <t>ersticken 4</t> geben. Das Schicksal von NSCs löst du am besten narrativ.","Jemand stolpert über die Knochen und knallt gegen die Wand (<t>Erschütterung 1</t>)","Sand rieselt von der Decke"],"box":[176.4,57.7,207.0,69.7],"p":229,"i":0,"sec":"die-grabhoehle"},{"t":"sh","x":"<b>MIA GUPTA</b>","sz":12.0,"box":[65.8,392.8,133.1,404.8],"p":229,"i":1,"sec":"die-grabhoehle"},{"t":"p","x":"<i>Verbündete</i>","sz":10.0,"box":[65.8,414.5,120.2,424.5],"p":229,"i":2,"sec":"die-grabhoehle"},{"t":"h","x":"IDENTITÄT","sz":10.0,"box":[65.8,436.0,112.1,446.0],"p":229,"i":3,"sec":"die-grabhoehle"},{"t":"p","x":"Wo ist die Grenze zwischen Nahrung und Völlerei?.","sz":9.0,"box":[65.8,450.7,267.2,459.7],"p":229,"i":4,"sec":"die-grabhoehle"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[65.8,471.5,106.4,481.5],"p":229,"i":5,"sec":"die-grabhoehle"},{"t":"card","x":"<b><i>Hunger stillen</i></b>, <i>Food-Truck-Köchin</i>, <i>Auto reparieren</i>, <i>Hungernde speisen</i>, <i>Gusseiserne Pfanne</i>, <i>An seine Menschlichkeit erinnern</i>, <i>Nahrung finden</i>, <i>Chicken &amp; Egg Food Truck</i>, <i>Hindu-Devas herbeirufen</i>, <i>Aura barmherziger Anteilnahme</i>","sz":null,"k":"yellow","box":[66.0,485.0,268.7,543.2],"p":229,"i":6,"sec":"die-grabhoehle"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[65.8,555.0,122.7,565.0],"p":229,"i":7,"sec":"die-grabhoehle"},{"t":"card","x":"<i>Helfersyndrom</i>, <i>Schlechte Köchin</i>, <i>Drama-Queen</i>, <i>Kritisiere nie ihre Kochkünste</i>","sz":null,"k":"yellow","box":[66.0,568.5,253.4,590.7],"p":229,"i":8,"sec":"die-grabhoehle"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[65.8,602.5,172.5,612.5],"p":229,"i":9,"sec":"die-grabhoehle"},{"t":"p","x":"<b>Göttin der letzten Küche:</b> Wenn du mit den Stärken <b>Das Blatt wendest</b>, um anderen Nahrung zu geben, verdoppelt sich das Momentum. Du kannst wählen, den Effekt zu skalieren (für 1 Momentum).","sz":9.0,"box":[65.8,617.2,271.0,662.2],"p":229,"i":10,"sec":"die-grabhoehle"},{"t":"card","x":"EVAS LUXUSVILLA","sz":null,"k":"yellow","box":[299.8,60.2,476.6,83.5],"p":229,"i":11,"sec":"die-grabhoehle"},{"t":"ro","x":"Hier wohnt also das Monster: ein luxuriöses, modernes Haus im Ranch-Stil in einem der reichsten Viertel der Stadt. Um euch herum zirpen die Zikaden, und eine warme Brise weht, während ihr den Blick auf die bewaldete Anhöhe richtet, auf der das Haus steht. Private Sicherheitsleute in Designeranzügen laufen wachsam auf der Terrasse am Pool hin und her. Hinter ihnen, in einem luxuriös ausgestatteten Wohnzimmer, brennt Licht, aber es ist niemand da. Dieses bizarre Aufeinandertreffen von Ruhe und Spannung ist genau das, was man von Eva Rice erwartet.","sz":9.0,"box":[317.5,87.3,538.9,236.7],"p":229,"i":12,"sec":"die-grabhoehle"},{"t":"p","x":"Ihr Zuhause ist ein <b>Ablenkungsmanöver</b>: Ihr Herz ist nicht hier, sondern liegt im Hinterhof von <u>Evas Elternhaus</u> in <u>Fritzberg</u> begraben.","sz":9.5,"box":[309.0,245.7,539.1,280.2],"p":229,"i":13,"sec":"die-grabhoehle"},{"t":"p","x":"Wenn das Team Privatdetektiv Navarros letzte Nachricht falsch interpretiert und hierher kommt, um nach dem Herzen zu suchen, muss es an den Elite-Sicherheitsleuten und der Alarmanlage (s. S. 287) sowie an allen möglichen Riss-Sicherheitsleuten, die Eva angeheuert haben könnte, vorbei.","sz":9.5,"box":[309.0,288.8,536.5,360.8],"p":229,"i":14,"sec":"die-grabhoehle"},{"t":"p","x":"Versuche, Eva zu stellen, enden an der Türschwelle. Entweder verlangt sie von den SC, dass sie einen Termin im Büro von <u>Rice Immobilien</u> vereinbaren, oder sie ruft die Polizei, um „diese Eindringlinge zu entfernen“. Sie wird keine Besucher empfangen.","sz":9.5,"box":[309.0,369.5,535.5,429.0],"p":229,"i":15,"sec":"die-grabhoehle"},{"t":"card","x":"Nachforschungen im Haus fördern einen Entwurf von Evas (unveröffentlichter) Biografie zu Tage, aus dem hervorgeht, <b>dass <u>Evas Elternhaus</u> in <u>Fritzberg</u> liegt</b>.","sz":null,"k":"yellow","box":[309.3,440.9,541.7,499.7],"p":229,"i":16,"sec":"die-grabhoehle"},{"t":"card","x":"Als Belohnung könnte das Team <i>Belastende Beweise</i> finden, um Eva zu <i>Überführen</i>, z. B. Nachrichten an die Schläger:innen, die die Kanzlei verwüstet haben, oder geheime Memos von Rice Immobilien über vorsätzliche und gefährliche Fahrlässigkeit bei Arbeiten an den Gebäuden in Wildknock.","sz":null,"k":"yellow","box":[309.3,508.9,541.7,617.8],"p":229,"i":17,"sec":"die-grabhoehle"}],"size":[595.276,841.89]},"230":{"tab":"","blocks":[{"t":"h","x":"FRITZBERG","sz":16.0,"box":[79.7,68.9,153.6,84.9],"p":230,"i":0,"skip":true,"sec":"fritzberg"},{"t":"ro","x":"Einst ein dicht besiedeltes Viertel, ist Fritzberg heute ein endloses, verschneites Waldgebiet voller schwarzer, lebloser Baumstämme, die die Ruinen zerfallener Gebäude umstehen. Die Luft ist kalt und der Wald unheimlich still. Während ihr euch über die rissigen Reste eines Bürgersteigs bewegt, färbt sich der Himmel aschfahl, und die Dämmerung setzt ein. Irgendwo flackert ein Feuer auf und verschwindet bald wieder. Ihr nehmt ein leises Heulen in der Ferne wahr, könnt es aber nicht genau lokalisieren. Es ist kalt und trostlos, und ihr seid hungrig.","sz":9.0,"box":[62.4,87.3,283.8,236.7],"p":230,"i":1,"sec":"fritzberg"},{"t":"p","x":"Das Geisterviertel Fritzberg ist der Ort, an dem alles begann: Hier ist Evas Elternhaus, hier haben ihre Eltern sie vernachlässigt, so dass sie später erwachte und die beiden fraß, was das ganze Viertel ins Verderben stürzte. Vor allem aber hat Eva hier ihr Herz begraben.","sz":9.5,"box":[53.9,245.7,285.4,305.2],"p":230,"i":2,"sec":"fritzberg"},{"t":"p","x":"Durch das Vorhandensein des legendären, korrumpierenden Wendigo-Herzens und den Rückzug des Nebels hat sich das zerfallene Viertel in eine Enklave der legendären Jagdgründe der Kreatur verwandelt (wenn du die Kampagne spielst, hat Albion Fritzberg nicht übernommen, im Gegensatz zu den anderen Vierteln, die Eva verschlungen hat).","sz":9.5,"box":[53.9,313.8,283.9,398.3],"p":230,"i":3,"sec":"fritzberg"},{"t":"p","x":"Je nach dem Zeitpunkt der Ankunft der SC und eurer Geschichte kann dieser Ort für verschiedene Zwecke dienen:","sz":9.5,"box":[53.9,407.0,275.4,441.5],"p":230,"i":4,"sec":"fritzberg"},{"t":"p","x":"• <b>Eine traurige Szene</b>: Wenn die SC auf dem Weg zu <u>Evas Elternhaus</u> sind oder noch nicht danach suchen, könnte diese Szene die Zerstörung zeigen, die Eva gebracht hat, und die düstere Zukunft Wildknocks vorhersagen, wenn das Team Eva nicht aufhält.","sz":9.5,"box":[53.9,453.0,286.7,512.5],"p":230,"i":5,"sec":"fritzberg"},{"t":"p","x":"• <b>Eine geheimnisvolle Szene</b>: Wenn die SC <u>Evas Elternhaus</u> noch nicht gefunden haben, könnte diese Szene eine gruselige Ermittlungsszene sein, in der das Team in den Ruinen stöbert und Hinweise findet, die sie dorthin führen (s. u.) Das verlassene Viertel leidet voller","sz":9.5,"box":[309.0,62.5,540.7,147.0],"p":230,"i":6,"sec":"fritzberg"},{"t":"card","x":"unter <i>Schlechtem Handyempfang</i>, der Wald ist <i>Unheimlicher Schatten</i> und <i>Verwirrender Pfade</i>.","sz":null,"k":"yellow","box":[344.2,124.1,534.8,146.9],"p":230,"i":7,"sec":"fritzberg"},{"t":"p","x":"• <b>Eine Horrorszene</b>: Wenn die Gruppe weiß, wohin sie geht, aber die Sitzung Spannung gebrauchen könnte, lass das Team versuchen, <u>Evas Elternhaus</u> zu erreichen, bevor es der Wendigo-Psychose erliegt. Dann muss das Team <b>Ein Risiko eingehen</b> und sich einen Weg durch die schneebedeckten, überwucherten Ruinen des Viertels bahnen. Nutze den Zustand <t>hungrig</t> bei deinen harten Aktionen oder hässlichen Entscheidungen, um die Bedrohung zu verstärken. Der Wendigo selbst könnte sie hetzen, um sie zu verschlingen, ehe sie die Quelle seiner Macht erreichen.","sz":9.5,"box":[309.0,155.7,540.2,290.2],"p":230,"i":8,"sec":"fritzberg"},{"t":"card","x":"Verwitterte Plakate von Rice Immobilien mit der Aufschrift „Eva Rice – eine Tochter Fritzbergs“ verraten, dass <b>Eva hier geboren ist</b> und später das Viertel aufgekauft hat.","sz":null,"k":"yellow","box":[309.3,303.6,541.7,362.3],"p":230,"i":9,"sec":"fritzberg"},{"t":"card","x":"<b>Mit einem Blick hinter den Nebel</b> kann man einer Spur aus blutbefleckten Steinen und Knochen zu etwas folgen, das wie der Eingang zu einer unheimlichen Höhle aussieht, einem Schlund, aus dem es kein Entkommen gibt: <u>Evas Elternhaus.</u>","sz":null,"k":"yellow","box":[309.3,371.5,541.7,455.3],"p":230,"i":10,"sec":"fritzberg"}],"size":[595.276,841.89]},"231":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 4:","sz":14.0,"box":[53.9,61.9,122.1,75.9],"p":231,"i":0,"skip":true,"sec":"schicht-4-das-herz-des-boesen"},{"t":"h","x":"DAS HERZ DES BÖSEN","sz":23.0,"box":[53.9,84.2,257.2,107.2],"p":231,"i":1,"skip":true},{"t":"h","x":"EVAS ELTERNHAUS","sz":16.0,"box":[79.7,120.8,202.0,136.8],"p":231,"i":2,"skip":true,"sec":"evas-elternhaus"},{"t":"ro","x":"Inmitten eines abgerissenen Wohnungsbauprojekts, bedeckt mit einer Schicht aus Schnee und Eis, steht ein einsames altes Haus: Eva Rices Elternhaus. Es ist einstöckig, umgeben von einem morschen Lattenzaun und einem Hof voller zerbrochener Bierflaschen. Die abblätternde Fassade und der Geruch von Verfall lassen den Eindruck entstehen, dass es schon immer so vernachlässigt war, nie ein richtiges Zuhause. Die Haustür ist angelehnt, und die Fenster sind zerbrochen. Eine Windböe aus dem Inneren des Hauses trägt ein paar Schneeflocken in den Hof.","sz":9.0,"box":[62.4,139.2,283.8,288.6],"p":231,"i":3,"sec":"evas-elternhaus"},{"t":"p","x":"Jahre legendären Hungers und täglicher Gewalt haben das Haus, in dem Evas Herz ruht, in einen pulsierenden Kern des Bösen verwandelt. Im Hinterhof, unter einer Schicht vereister Erde, <b>liegt Evas Herz begraben</b>.","sz":9.5,"box":[53.9,297.6,286.3,344.7],"p":231,"i":4,"sec":"evas-elternhaus"},{"t":"p","x":"Sobald jemand einen Fuß in die Nähe des Hauses oder ins Haus setzt und damit Schicht 4 eröffnet, erwischt ihn die Wendigo-Psychose auf Stufe 4. Außerdem wird Eva instinktiv die Anwesenheit des Teams spüren und zurückeilen, wenn sie nicht bereits hier ist (sie wird sich nicht auflösen, da es zu lange dauern könnte, bis sie sich wieder zusammensetzt). Je nach Evas Position hat das Team entweder keine Zeit mehr, nur sehr wenig oder alle Zeit der Welt. Selbst mit der Geschwindigkeit eines Monsters könnte sie zu weit weg sein, um rechtzeitig hierher zu kommen, vor allem, wenn die SC sie erfolgreich an einen anderen Ort gelockt haben (das Gerichtsgebäude vielleicht?)","sz":9.5,"box":[53.9,353.3,285.1,512.8],"p":231,"i":5,"sec":"evas-elternhaus"},{"t":"sh","x":"<b>DAS HERZ</b>","sz":10.0,"box":[54.3,526.4,108.4,536.4],"p":231,"i":6,"sec":"evas-elternhaus"},{"t":"p","x":"Wenn die Zeit drängt, muss das Team das Herz aus dem gefrorenen Boden ausgraben, wozu es den Maximalwert von <i>Ausgegraben 5</i> erreichen muss. Andernfalls kannst du dies erzählerisch lösen. Wenn man es exhumiert, ist das Herz in einen blutigen Lappen gewickelt, verschrumpelt und geschwärzt. Sobald jemand das Herz besitzt, kann die betreffende Person:","sz":9.5,"box":[53.9,541.9,285.1,626.4],"p":231,"i":7,"sec":"evas-elternhaus"},{"t":"p","x":"• Es mit einer silbernen Waffe zerteilen, was Eva auf der Stelle tötet. Wenn Eva oder jemand anderes Gegenwehr leistet, folgt eine <b>Direkte Konfrontation</b>.","sz":9.5,"box":[53.9,638.0,279.5,672.6],"p":231,"i":8,"sec":"evas-elternhaus"},{"t":"p","x":"• Es wieder in Eva stecken, wenn sie gefesselt ist, so dass sie den überwältigenden Schmerz all ihrer verdrängten Emotionen spürt, vor allem legendäre Schuldgefühle (wie bei ihrer Aktion <b>Herzlos</b>).","sz":9.5,"box":[53.9,681.1,275.3,728.2],"p":231,"i":9,"sec":"evas-elternhaus"},{"t":"p","x":"• Eva damit drohen, um sie zu <b>Überzeugen</b>. Jeder Treffer, selbst die Androhung des kleinsten <t>Schnittes 1</t> ins Herz mit einer Silberwaffe, würde ausreichen, um sie zur Kooperation zu bewegen. Bei einem Fehlschlag wird sie, wenn sie nah genug ist, vorspringen und das Herz schnappen. Wenn sie zu weit weg ist, wird Eva die Befehle des SC ausführen, bis sie eine weitere Chance bekommt.","sz":9.5,"box":[309.0,62.5,536.1,159.5],"p":231,"i":10,"sec":"evas-elternhaus"},{"t":"p","x":"• Jede kreative Lösung wie <b>Jetzt reicht‘s</b>, um die Essenz des Wendigos mystisch zu manipulieren (wenn die SC in darin ausgebildet sind) ist ebenfalls denkbar. Man kann Eva nicht von dem Mythos „heilen“, wohl aber in Schlaf versetzen oder ihren Mythos mit dem Ofen der Hexe (<i>Athanor</i>, S. 108) entfernen.","sz":9.5,"box":[309.0,168.2,537.7,240.2],"p":231,"i":11,"sec":"evas-elternhaus"},{"t":"card","x":"Wenn sie dem Team ausgeliefert ist oder als Teil ihrer letzten Worte kann Eva alle Lücken über ihre Vergangenheit und ihre Projekte schließen und belastende Beweise liefern.","sz":null,"k":"yellow","box":[309.3,253.2,541.7,312.2],"p":231,"i":12,"sec":"evas-elternhaus"},{"t":"p","x":"Eva behauptet, Vince Beaumont (sie nennt ihn beim Namen der aktuellen Reinkarnation) sei ihr Komplize: Er wusste von den Gräueltaten, die sie beging, um die Stadtviertel zu entwerten, und unterstützte sie, weil er so sein Königreich Albion vergrößern konnte. Er befahl den Fahrenden, Einwohner:innen einzuschüchtern, die sich gegen Rice Immobilien aussprachen, indem sie zum Beispiel Jackie Clarkes Büro verwüsteten.","sz":10.0,"box":[317.5,326.9,532.2,449.4],"p":231,"i":13,"sec":"evas-elternhaus"},{"t":"h","x":"BEAUMONTS TROPHÄE","sz":14.0,"box":[320.3,481.2,425.6,495.2],"p":231,"i":14,"sec":"evas-elternhaus"},{"t":"p","x":"Wenn du die Kampagne leitest, erwacht Beaumonts Interesse an dem Fall wieder, wenn das Team der Tötung des Wendigos näher kommt. Beaumont will, dass der Wendigo in Albion stirbt, wo er die Prophezeiung des Questentiers erfüllen kann (s. S. 177).","sz":9.0,"box":[320.3,507.7,525.6,564.7],"p":231,"i":15,"sec":"evas-elternhaus"},{"t":"p","x":"Wenn er das Team nach Wildknock geschickt hat, wird er es nun kontaktieren und befehlen, Eva lebendig zu fangen oder ihr Herz zu holen und sie zu zwingen, den SC nach Albion zu folgen, damit sie dort sterben kann. Er bietet Unterstützung an. Wenn er ein Feind des Teams ist, wird er sich in die Karten schauen lassen und sich ehrlich zu zeigen, indem er den SC sagt, dass das Herz für ihn äußerst wertvoll ist. Er wird einen Waffenstillstand anbieten und ist bereit, mehr zu geben, denn er ist sicher, dass er nach Erfüllung der Prophezeiung in der Lage sein wird, alles zurückzugewinnen.","sz":9.0,"box":[320.3,573.4,526.7,714.4],"p":231,"i":16,"sec":"evas-elternhaus"},{"t":"p","x":"Dies führt zum <u>steinernen Altar</u> in der Exposition des nächsten Falls, <i>Die Straßen bluten Neon</i> (s. S. 244).","sz":9.0,"box":[320.3,723.1,529.5,744.1],"p":231,"i":17,"sec":"evas-elternhaus"}],"size":[595.276,841.89]},"232":{"tab":"","blocks":[{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[40.9,57.9,161.9,83.5],"p":232,"i":0,"sec":"evas-elternhaus"},{"t":"p","x":"Im Folgenden findest du einige Fragen, die du dir stellen solltest, und Punkte, die es beim Abschluss dieses Falles noch einmal zu überdenken gilt:","sz":9.5,"box":[53.9,94.9,282.3,129.4],"p":232,"i":1,"sec":"evas-elternhaus"},{"t":"p","x":"• Wo ist Eva? Lebt sie? Ist sie auf freiem Fuß? Oder hat das Team sie gefangen genommen und ein SC, der ihr Herz besitzt, sie zur Kooperation gezwungen? Wenn ja, planen die SC, sie auf Beaumonts Befehl hinzurichten? Oder versuchen sie, eine Lösung für die Situation zu finden?","sz":9.5,"box":[53.9,140.9,285.1,212.9],"p":232,"i":2,"sec":"evas-elternhaus"},{"t":"p","x":"• Wie sind die SC aus der Konfrontation mit ihren Überlebensinstinkten hervorgegangen? Konnten sie dem Hunger widerstehen oder sind sie ihm erlegen? Was in Wildknock passiert ist, muss höchstwahrscheinlich in Wildknock bleiben. Wie haben sie den Zusammenstoß mit dem kannibalischen Wendigo überstanden? Haben sie noch alle Gliedmaßen?","sz":9.5,"box":[53.9,221.5,281.3,306.0],"p":232,"i":3,"sec":"evas-elternhaus"},{"t":"p","x":"• Wenn das Team Eva aus dem Verkehr zieht oder sie von der Bildfläche verschwindet, was wird aus Rice Immobilien? Arbeitet die Firma in Zukunft legal? Lösen die Behörden sie auf und verwenden ihr Vermögen zum Wiederaufbau der Viertel, die sie ruiniert hat? Wer in der Firma war in die dunklen Machenschaften verwickelt, und wird man sie zur Rechenschaft ziehen?","sz":9.5,"box":[53.9,314.7,286.3,411.7],"p":232,"i":4,"sec":"evas-elternhaus"},{"t":"p","x":"• Wie steht es um Wildknock? Ist der Prozess der Albionisierung fortgeschritten? Wird Rice Immobilien beenden, was die Firma begonnen hat? Oder werden gute Menschen wie Pfarrerin Williams, Alex Penn, Otto Scholz und Mia Gupta helfen, das Viertel aufzubauen und zu bevölkern, um es zu retten?","sz":9.5,"box":[53.9,420.4,285.6,492.4],"p":232,"i":5,"sec":"evas-elternhaus"},{"t":"p","x":"• Hat Luis Navarro seinen Frieden gefunden? Wie wird man sich an ihn erinnern – als irren Schnüffler oder als den wahren Helden, der er war? Was ist mit Jackie Clarke, der Rechtsanwältin, die immer allen geholfen hat? Wird sie ein Vermächtnis hinterlassen?","sz":9.5,"box":[53.9,501.0,286.1,560.5],"p":232,"i":6,"sec":"evas-elternhaus"},{"t":"p","x":"• Wenn das Team Evas Herz aus ihrem Elternhaus entfernt hat, was wird aus Fritzberg? Wird es zum Neubaugebiet, oder wird ein größeres Übel das Gebiet, in dem der Nebel so dünn ist, übernehmen?","sz":9.5,"box":[53.9,569.2,284.7,616.2],"p":232,"i":7,"sec":"evas-elternhaus"}],"size":[595.276,841.89]}},"figures":[{"id":"eisberg","page":212,"kind":"eisberg","title":"Der Eisberg","file":"img/case08/eisberg.webp","box":[0,352,595,785],"after":null},{"id":"titel","page":209,"kind":"art","title":"Daheim ist daheim – Titelbild","file":"img/case08/titel.webp","box":[0,0,595,796],"after":null},{"id":"werwolf","page":215,"kind":"art","title":"Thorn Sørensen als Werwolf","file":"img/case08/werwolf.webp","box":[0,522,595,796],"after":null},{"id":"navarro","page":220,"kind":"art","title":"Detektiv Navarros Geist","file":"img/case08/navarro.webp","box":[0,0,293,796],"after":null},{"id":"rice-buero","page":225,"kind":"art","title":"Eva Rice und Mr. Barlow-Typ im Büro","file":"img/case08/rice-buero.webp","box":[10,0,595,362],"after":null},{"id":"ungeheuer","page":228,"kind":"art","title":"Das Monster in der Grabhöhle","file":"img/case08/ungeheuer.webp","box":[0,0,595,356],"after":null},{"id":"karte-mia","page":229,"kind":"handout","title":"Themenkarte: Mia Gupta","file":"img/case08/karte-mia.webp","box":[50,377,287,691],"after":null}],"eisberg":{"page":212,"fig":"eisberg","nodes":[{"label":"Städtische Beamte","layer":0,"x":29.4,"y":49.1,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Verlassene Hauptstraße","layer":0,"x":44.1,"y":48.7,"w":11,"h":9.5,"target":"verlassene-hauptstrasse"},{"label":"Eine Queste von Artus","layer":0,"x":58.9,"y":49.1,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Im Auftrag der Pfarrerin","layer":0,"x":72.8,"y":49.1,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Kanzlei Clarke","layer":1,"x":38.7,"y":58.5,"w":11,"h":9.5,"target":"kanzlei-clarke"},{"label":"Chicken & Egg Food Truck","layer":1,"x":52.4,"y":58.5,"w":11,"h":9.5,"target":"chicken-egg-food-truck"},{"label":"Kirche des Heiligen Geistes","layer":1,"x":66.1,"y":58.5,"w":11,"h":9.5,"target":"kirche-des-heiligen-geistes"},{"label":"Rice Immobilien","layer":2,"x":40.0,"y":66.8,"w":11,"h":9.5,"target":"rice-immobilien"},{"label":"Zuhause der Navarros","layer":2,"x":53.3,"y":66.8,"w":11,"h":9.5,"target":"zuhause-der-navarros"},{"label":"Grey Alley","layer":2,"x":66.3,"y":66.8,"w":11,"h":9.5,"target":"grey-alley"},{"label":"Fritzberg","layer":3,"x":38.9,"y":73.4,"w":11,"h":9.5,"target":"fritzberg"},{"label":"Grabhöhle","layer":3,"x":53.3,"y":74.2,"w":11,"h":9.5,"target":"die-grabhoehle"},{"label":"Evas Luxusvilla","layer":3,"x":65.6,"y":74.2,"w":11,"h":9.5,"target":"schicht-3"},{"label":"Evas Elternhaus","layer":4,"x":50.6,"y":82.1,"w":11,"h":9.5,"target":"evas-elternhaus"}]}};
